const WM_MOUSELEAVE_MSG: u32 = 0x02A3;
const WM_MOUSEWHEEL_MSG: u32 = 0x020A;
const WM_APP_INSTALLED_READY: u32 = 0x8000 + 402;
const WM_APP_WP_THUMB_READY: u32 = 0x8000 + 403;
const WM_APP_WP_LIST_READY: u32 = 0x8000 + 404;

#[derive(Clone, Copy, PartialEq, Eq)]
enum WallpaperStatusKind {
    Active,
    Loading,
    Error,
    Stopped,
}

fn classify_wallpaper_status(status: &str) -> WallpaperStatusKind {
    let low = status.to_ascii_lowercase();
    if low.contains("failed")
        || low.contains("error")
        || low.contains("no wallpaper")
        || low.contains("not presented")
    {
        WallpaperStatusKind::Error
    } else if low.contains("loading") || low.contains("initializing") || low.contains("syncing") {
        WallpaperStatusKind::Loading
    } else if low.contains("active") || low.contains("playing") || low.contains("paused") {
        WallpaperStatusKind::Active
    } else {
        WallpaperStatusKind::Stopped
    }
}

/// Non-blocking Direct2D thumbnail cache for Wallpaper Studio cards (both `.mp4`/video frames and
/// static `.png`/`.jpg`/`.webp` images). Decodes off-thread and posts `WM_APP_WP_THUMB_READY`.
struct WallpaperThumbCache {
    tx: Option<std::sync::mpsc::Sender<(String, usize)>>,
    rx: Option<std::sync::mpsc::Receiver<(String, Option<(u32, u32, Vec<u8>)>)>>,
    in_flight: HashSet<String>,
    decoded: HashMap<String, Option<(u32, u32, Vec<u8>)>>,
    bitmaps: HashMap<String, ID2D1Bitmap>,
}

impl WallpaperThumbCache {
    fn new() -> Self {
        Self {
            tx: None,
            rx: None,
            in_flight: HashSet::new(),
            decoded: HashMap::new(),
            bitmaps: HashMap::new(),
        }
    }

    fn ensure_worker(&mut self) {
        if self.tx.is_some() {
            return;
        }
        let (req_tx, req_rx) = std::sync::mpsc::channel::<(String, usize)>();
        let (res_tx, res_rx) =
            std::sync::mpsc::channel::<(String, Option<(u32, u32, Vec<u8>)>)>();
        let _ = std::thread::Builder::new()
            .name("autumn-wp-thumbs".to_string())
            .spawn(move || {
                while let Ok((path, hwnd_raw)) = req_rx.recv() {
                    let key = path.to_ascii_lowercase();
                    let pix = decode_wallpaper_thumbnail_bgra(&path, 192, 128)
                        .map(|bgra| (192u32, 128u32, bgra));
                    if res_tx.send((key, pix)).is_err() {
                        break;
                    }
                    if hwnd_raw != 0 {
                        unsafe {
                            let _ = PostMessageW(
                                Some(HWND(hwnd_raw as *mut c_void)),
                                WM_APP_WP_THUMB_READY,
                                WPARAM(0),
                                LPARAM(0),
                            );
                        }
                    }
                }
            });
        self.tx = Some(req_tx);
        self.rx = Some(res_rx);
    }

    fn drain_ready(&mut self) -> bool {
        let Some(ref rx) = self.rx else {
            return false;
        };
        let mut any = false;
        while let Ok((key, pix)) = rx.try_recv() {
            self.in_flight.remove(&key);
            if self.decoded.len() >= 32 && !self.decoded.contains_key(&key) {
                self.decoded.clear();
                self.bitmaps.clear();
            }
            self.decoded.insert(key, pix);
            any = true;
        }
        any
    }

    fn sync_visible(&mut self, paths: &[&str], rt: &ID2D1DCRenderTarget, notify_hwnd: HWND) {
        self.drain_ready();
        for &raw in paths {
            let p = raw.trim();
            if p.is_empty() {
                continue;
            }
            let key = p.to_ascii_lowercase();
            if self.bitmaps.contains_key(&key) {
                continue;
            }
            if let Some(entry) = self.decoded.get(&key) {
                if let Some((w, h, ref bgra)) = entry {
                    let props = D2D1_BITMAP_PROPERTIES {
                        pixelFormat: D2D1_PIXEL_FORMAT {
                            format: DXGI_FORMAT_B8G8R8A8_UNORM,
                            alphaMode: D2D1_ALPHA_MODE_PREMULTIPLIED,
                        },
                        dpiX: 96.0,
                        dpiY: 96.0,
                    };
                    if let Ok(bmp) = unsafe {
                        rt.CreateBitmap(
                            D2D_SIZE_U { width: *w, height: *h },
                            Some(bgra.as_ptr() as *const c_void),
                            *w * 4,
                            &props,
                        )
                    } {
                        self.bitmaps.insert(key, bmp);
                    }
                }
                continue;
            }
            if !self.in_flight.contains(&key) {
                self.ensure_worker();
                if let Some(ref tx) = self.tx {
                    if tx.send((p.to_string(), notify_hwnd.0 as usize)).is_ok() {
                        self.in_flight.insert(key);
                    }
                }
            }
        }
    }

    fn get(&self, path: &str) -> Option<&ID2D1Bitmap> {
        if path.trim().is_empty() {
            return None;
        }
        self.bitmaps.get(&path.trim().to_ascii_lowercase())
    }

    fn invalidate(&mut self) {
        self.bitmaps.clear();
        self.decoded.clear();
        self.in_flight.clear();
    }
}

/// Fills `rr` with `bmp` using aspect-fill cover scaling and crisp antialiased rounded corners
/// via `ID2D1BitmapBrush` (zero `ID2D1Layer` allocation).
unsafe fn draw_rounded_bitmap_cover(
    rt: &ID2D1DCRenderTarget,
    bmp: &ID2D1Bitmap,
    rr: &D2D1_ROUNDED_RECT,
) -> bool {
    let sz = bmp.GetSize();
    let bw = sz.width.max(1.0);
    let bh = sz.height.max(1.0);
    let dw = (rr.rect.right - rr.rect.left).max(1.0);
    let dh = (rr.rect.bottom - rr.rect.top).max(1.0);
    let sc = (dw / bw).max(dh / bh);
    let ox = rr.rect.left + (dw - bw * sc) * 0.5;
    let oy = rr.rect.top + (dh - bh * sc) * 0.5;
    let bb_props = D2D1_BITMAP_BRUSH_PROPERTIES {
        extendModeX: D2D1_EXTEND_MODE_CLAMP,
        extendModeY: D2D1_EXTEND_MODE_CLAMP,
        interpolationMode: D2D1_BITMAP_INTERPOLATION_MODE_LINEAR,
    };
    let br_props = D2D1_BRUSH_PROPERTIES {
        opacity: 1.0,
        transform: Matrix3x2 {
            M11: sc,
            M12: 0.0,
            M21: 0.0,
            M22: sc,
            M31: ox,
            M32: oy,
        },
    };
    if let Ok(brush) = rt.CreateBitmapBrush(bmp, Some(&bb_props), Some(&br_props)) {
        rt.FillRoundedRectangle(rr, &brush);
        true
    } else {
        false
    }
}
