const STUDIO_PREVIEW_BANDS: [f32; 12] = [
    0.42, 0.68, 0.84, 0.56, 0.92, 0.74, 0.62, 0.80, 0.52, 0.66, 0.44, 0.32,
];

#[inline]
fn effective_preview_bands(live: &[f32; 12]) -> [f32; 12] {
    if live.iter().copied().sum::<f32>() > 0.04 {
        *live
    } else {
        STUDIO_PREVIEW_BANDS
    }
}

