fn music_layout_toggles(cfg: &AppConfig) -> Vec<(&'static str, bool, HitZone)> {
    let cover_lbl = match cfg.music_style {
        MusicStyle::VinylDeck | MusicStyle::TurntablePro => "Show Vinyl Platter & Cover",
        _ => "Show Album Cover Art",
    };
    let viz_lbl = match cfg.music_style {
        MusicStyle::CassetteDeck => "Show Tape Reels & Window",
        MusicStyle::AnalogVuMeter => "Show Analog VU Meters",
        _ => "Show Audio Spectrum Visualizer",
    };
    let mut out = vec![
        (cover_lbl, cfg.music_show_cover, HitZone::ToggleMusicCover),
        ("Show Track Title", cfg.music_show_title, HitZone::ToggleMusicTitle),
        ("Show Artist & Album Subtitle", cfg.music_show_artist, HitZone::ToggleMusicArtist),
        ("Show Transport Controls", cfg.music_show_controls, HitZone::ToggleMusicControls),
        (viz_lbl, cfg.music_show_viz, HitZone::ToggleMusicViz),
        ("Show Header Status Badge", cfg.music_show_badge, HitZone::ToggleMusicBadge),
    ];
    if cfg.music_style != MusicStyle::CassetteDeck {
        out.push(("Eco Visualizer (24 FPS)", cfg.viz_eco_fps, HitZone::ToggleVizEcoFps));
    }
    out
}

fn ext_widget_supports_align(id: ExtWidgetId) -> bool {
    id == ExtWidgetId::Greeting
}

fn ext_widget_supports_compact(id: ExtWidgetId) -> bool {
    matches!(id, ExtWidgetId::Weather | ExtWidgetId::Network | ExtWidgetId::Gpu)
}

fn ext_layout_toggles(id: ExtWidgetId, wcfg: &ExtWidgetConfig) -> Vec<(&'static str, bool, HitZone)> {
    let hdr_lbl = match id {
        ExtWidgetId::SearchBar => "Show Search Prompt Text",
        _ => "Show Header Title Bar",
    };
    let pri_lbl = match id {
        ExtWidgetId::SearchBar => "Show Engine Badge Pill",
        ExtWidgetId::Weather => "Show Temperature Readout",
        ExtWidgetId::Pomodoro => "Show Countdown Timer",
        ExtWidgetId::Notes => "Show Checklist Tasks",
        ExtWidgetId::Calendar => "Show Month & Day Grid",
        _ => "Show Primary Readout",
    };
    let icon_lbl = match id {
        ExtWidgetId::SearchBar => "Show Search Engine Icon",
        ExtWidgetId::Weather => "Show Sky Condition Icon",
        ExtWidgetId::RecycleBin => "Show Bin Status Icon",
        _ => "Show Accent Icon / Orb",
    };
    let div_lbl = match id {
        ExtWidgetId::SearchBar => "Show Input Frame & Rim",
        _ => "Show Dividers & Bars",
    };
    let footer_lbl = match id {
        ExtWidgetId::SearchBar => "Show Quick Search Hints",
        _ => "Show Secondary Metadata",
    };
    vec![
        ("Glass Plate Backdrop", wcfg.show_plate, HitZone::ToggleExtPlate),
        (hdr_lbl, wcfg.show_header, HitZone::ToggleExtHeader),
        (pri_lbl, wcfg.show_primary, HitZone::ToggleExtPrimary),
        (icon_lbl, wcfg.show_icon, HitZone::ToggleExtIcon),
        (div_lbl, wcfg.show_dividers, HitZone::ToggleExtDividers),
        (footer_lbl, wcfg.show_footer, HitZone::ToggleExtFooter),
    ]
}

