struct DibBuffer {
    mem_dc: HDC,
    bitmap: HBITMAP,
    old_obj: HGDIOBJ,
    #[cfg_attr(not(test), allow(dead_code))]
    bits: *mut u8,
    width: i32,
    height: i32,
}

impl DibBuffer {
    fn new() -> Self {
        Self {
            mem_dc: HDC::default(),
            bitmap: HBITMAP::default(),
            old_obj: HGDIOBJ::default(),
            bits: std::ptr::null_mut(),
            width: 0,
            height: 0,
        }
    }

    fn ensure_size(&mut self, w: i32, h: i32) -> bool {
        let w = w.max(2);
        let h = h.max(2);
        if !self.mem_dc.0.is_null() && self.width == w && self.height == h {
            return true;
        }
        self.release();
        unsafe {
            let dc = CreateCompatibleDC(None);
            if dc.0.is_null() {
                return false;
            }
            let bmi = BITMAPINFO {
                bmiHeader: BITMAPINFOHEADER {
                    biSize: size_of::<BITMAPINFOHEADER>() as u32,
                    biWidth: w,
                    biHeight: -h,
                    biPlanes: 1,
                    biBitCount: 32,
                    biCompression: BI_RGB.0,
                    ..Default::default()
                },
                ..Default::default()
            };
            let mut bits: *mut core::ffi::c_void = std::ptr::null_mut();
            let Ok(bmp) = CreateDIBSection(Some(dc), &bmi, DIB_RGB_COLORS, &mut bits, None, 0)
            else {
                let _ = DeleteDC(dc);
                return false;
            };
            let old = SelectObject(dc, HGDIOBJ(bmp.0));
            self.mem_dc = dc;
            self.bitmap = bmp;
            self.old_obj = old;
            self.bits = bits as *mut u8;
            self.width = w;
            self.height = h;
            true
        }
    }

    fn release(&mut self) {
        unsafe {
            if !self.mem_dc.0.is_null() {
                if !self.old_obj.0.is_null() {
                    let _ = SelectObject(self.mem_dc, self.old_obj);
                }
                if !self.bitmap.0.is_null() {
                    let _ = DeleteObject(HGDIOBJ(self.bitmap.0));
                }
                let _ = DeleteDC(self.mem_dc);
            }
        }
        self.mem_dc = HDC::default();
        self.bitmap = HBITMAP::default();
        self.old_obj = HGDIOBJ::default();
        self.bits = std::ptr::null_mut();
        self.width = 0;
        self.height = 0;
    }
}

impl Drop for DibBuffer {
    fn drop(&mut self) {
        self.release();
    }
}

struct PaintResources {
    u: f32,
    bg_grad: Option<ID2D1LinearGradientBrush>,
    glow_grad: Option<ID2D1LinearGradientBrush>,
    cream: ID2D1SolidColorBrush,
    warm_sub: ID2D1SolidColorBrush,
    muted_txt: ID2D1SolidColorBrush,
    sun_gold: ID2D1SolidColorBrush,
    amber_dim: ID2D1SolidColorBrush,
    sage: ID2D1SolidColorBrush,
    coral: ID2D1SolidColorBrush,
    card_bg: ID2D1SolidColorBrush,
    card_hover: ID2D1SolidColorBrush,
    card_active: ID2D1SolidColorBrush,
    card_border: ID2D1SolidColorBrush,
    dark_ink: ID2D1SolidColorBrush,
    tf_h1: IDWriteTextFormat,
    tf_badge: IDWriteTextFormat,
    tf_sec: IDWriteTextFormat,
    tf_title: IDWriteTextFormat,
    tf_toggle: IDWriteTextFormat,
    tf_sub: IDWriteTextFormat,
    tf_btn: IDWriteTextFormat,
    tf_right: IDWriteTextFormat,
    round_cap: Option<ID2D1StrokeStyle>,
}

impl PaintResources {
    fn create(
        rt: &ID2D1DCRenderTarget,
        dw: &IDWriteFactory,
        d2d: &ID2D1Factory,
        win_w: f32,
        win_h: f32,
        u: f32,
    ) -> Option<Self> {
        unsafe {
            let bg_stops = [
                D2D1_GRADIENT_STOP { position: 0.0, color: rgb_u8(22, 17, 14, 1.0) },
                D2D1_GRADIENT_STOP { position: 0.5, color: rgb_u8(16, 13, 11, 1.0) },
                D2D1_GRADIENT_STOP { position: 1.0, color: rgb_u8(12, 10, 9, 1.0) },
            ];
            let bg_grad = create_grad(rt, Vector2 { X: 0.0, Y: 0.0 }, Vector2 { X: win_w, Y: win_h }, &bg_stops);

            let glow_stops = [
                D2D1_GRADIENT_STOP { position: 0.0, color: rgb_u8(245, 166, 66, 0.10) },
                D2D1_GRADIENT_STOP { position: 1.0, color: rgb_u8(245, 166, 66, 0.0) },
            ];
            let glow_grad = create_grad(rt, Vector2 { X: 0.0, Y: 0.0 }, Vector2 { X: 0.0, Y: 105.0 * u }, &glow_stops);

            let round_cap = d2d
                .CreateStrokeStyle(
                    &D2D1_STROKE_STYLE_PROPERTIES {
                        startCap: D2D1_CAP_STYLE_ROUND,
                        endCap: D2D1_CAP_STYLE_ROUND,
                        ..Default::default()
                    },
                    None,
                )
                .ok();

            Some(Self {
                u,
                bg_grad,
                glow_grad,
                cream: solid(rt, rgb_u8(255, 243, 220, 0.96))?,
                warm_sub: solid(rt, rgb_u8(206, 188, 164, 0.80))?,
                muted_txt: solid(rt, rgb_u8(160, 144, 126, 0.65))?,
                sun_gold: solid(rt, rgb_u8(245, 172, 72, 1.0))?,
                amber_dim: solid(rt, rgb_u8(245, 166, 66, 0.22))?,
                sage: solid(rt, rgb_u8(140, 192, 132, 0.96))?,
                coral: solid(rt, rgb_u8(242, 109, 82, 0.95))?,
                card_bg: solid(rt, rgb_u8(29, 23, 20, 0.92))?,
                card_hover: solid(rt, rgb_u8(38, 30, 25, 0.96))?,
                card_active: solid(rt, rgb_u8(44, 33, 24, 0.98))?,
                card_border: solid(rt, rgb_u8(255, 243, 220, 0.08))?,
                dark_ink: solid(rt, rgb_u8(18, 13, 10, 0.98))?,
                tf_h1: make_tf(dw, 17.0 * u, DWRITE_FONT_WEIGHT_BOLD, DWRITE_TEXT_ALIGNMENT_LEADING),
                tf_badge: make_tf(dw, 9.5 * u, DWRITE_FONT_WEIGHT_BOLD, DWRITE_TEXT_ALIGNMENT_CENTER),
                tf_sec: make_tf(dw, 10.0 * u, DWRITE_FONT_WEIGHT_BOLD, DWRITE_TEXT_ALIGNMENT_LEADING),
                tf_title: make_tf(dw, 12.6 * u, DWRITE_FONT_WEIGHT_SEMI_BOLD, DWRITE_TEXT_ALIGNMENT_LEADING),
                tf_toggle: make_tf(dw, 11.4 * u, DWRITE_FONT_WEIGHT_SEMI_BOLD, DWRITE_TEXT_ALIGNMENT_LEADING),
                tf_sub: make_tf(dw, 10.2 * u, DWRITE_FONT_WEIGHT_REGULAR, DWRITE_TEXT_ALIGNMENT_LEADING),
                tf_btn: make_tf(dw, 11.2 * u, DWRITE_FONT_WEIGHT_SEMI_BOLD, DWRITE_TEXT_ALIGNMENT_CENTER),
                tf_right: make_tf(dw, 11.0 * u, DWRITE_FONT_WEIGHT_MEDIUM, DWRITE_TEXT_ALIGNMENT_TRAILING),
                round_cap,
            })
        }
    }
}

pub fn register_settings_class(
    hinst: HINSTANCE,
    wnd_proc: unsafe extern "system" fn(HWND, u32, WPARAM, LPARAM) -> LRESULT,
) {
    unsafe {
        let mut wc = WNDCLASSEXW::default();
        wc.cbSize = size_of::<WNDCLASSEXW>() as u32;
        wc.lpfnWndProc = Some(wnd_proc);
        wc.hInstance = hinst;
        wc.hCursor = LoadCursorW(None, IDC_ARROW).unwrap_or_default();
        wc.lpszClassName = w!("AutumnSettingsWnd");
        let _ = RegisterClassExW(&wc);
    }
}

