fn create_settings_dc_rt(f: &ID2D1Factory) -> Option<ID2D1DCRenderTarget> {
    let props = D2D1_RENDER_TARGET_PROPERTIES {
        r#type: D2D1_RENDER_TARGET_TYPE_DEFAULT,
        pixelFormat: D2D1_PIXEL_FORMAT {
            format: DXGI_FORMAT_B8G8R8A8_UNORM,
            alphaMode: D2D1_ALPHA_MODE_PREMULTIPLIED,
        },
        dpiX: 96.0,
        dpiY: 96.0,
        usage: D2D1_RENDER_TARGET_USAGE_GDI_COMPATIBLE,
        ..Default::default()
    };
    unsafe { f.CreateDCRenderTarget(&props).ok() }
}

pub fn compute_canvas_snap(
    raw_dx: i16,
    raw_dy: i16,
    elem_idx: usize,
    target: WidgetCanvasTarget,
    boxes: &[ClockElemBox; 8],
    sc: f32,
    u: f32,
    alt_held: bool,
) -> (i16, i16, Option<f32>, Option<f32>) {
    let clamped_dx = raw_dx.clamp(-280, 280);
    let clamped_dy = raw_dy.clamp(-180, 180);
    if alt_held {
        return (clamped_dx, clamped_dy, None, None);
    }
    let u = u.max(0.5);
    let sc = sc.max(0.25);
    let thresh: i16 = 4; // 4px magnetic snap threshold in widget logical units
    let b_cur = boxes[elem_idx.min(7)];
    let base_cx = b_cur.base_cx / u;
    let base_cy = b_cur.base_cy / u;
    let cur_hw = b_cur.tr_half_w / u;
    let cur_hh = b_cur.tr_half_h / u;

    let mut best_dx = clamped_dx;
    let mut best_dist_x = thresh + 1;
    let mut snap_line_x: Option<f32> = None;

    let mut best_dy = clamped_dy;
    let mut best_dist_y = thresh + 1;
    let mut snap_line_y: Option<f32> = None;

    // 1. Snap to Widget / Element Origin Center (0, 0) takes priority within ±4px home zone
    if clamped_dx.abs() <= thresh {
        best_dist_x = 0;
        best_dx = 0;
        snap_line_x = Some(if base_cx > 1.0 { base_cx } else { 380.0 });
    }
    if clamped_dy.abs() <= thresh {
        best_dist_y = 0;
        best_dy = 0;
        snap_line_y = Some(if base_cy > 1.0 { base_cy } else { 232.0 });
    }

    if b_cur.visible && !b_cur.elem_hidden {
        let mut try_snap_x = |target_dx: i16, guide_x: f32| {
            let d = (clamped_dx - target_dx).abs();
            if d <= thresh && d < best_dist_x {
                best_dist_x = d;
                best_dx = target_dx.clamp(-280, 280);
                snap_line_x = Some(guide_x);
            }
        };
        let mut try_snap_y = |target_dy: i16, guide_y: f32| {
            let d = (clamped_dy - target_dy).abs();
            if d <= thresh && d < best_dist_y {
                best_dist_y = d;
                best_dy = target_dy.clamp(-180, 180);
                snap_line_y = Some(guide_y);
            }
        };

        let n = target.elem_count().min(8);
        let card_idx = (0..n)
            .find(|&i| target.is_card_slot(i))
            .unwrap_or(n.saturating_sub(1));

        // 2. Snap to Card Center & Inner Padding Margins (10px logical padding)
        if elem_idx != card_idx && boxes[card_idx].visible {
            let bc = boxes[card_idx];
            let ccx = bc.cx / u;
            let ccy = bc.cy / u;
            let chw = bc.tr_half_w / u;
            let chh = bc.tr_half_h / u;
            let pad = 10.0 * sc;

            try_snap_x(((ccx - base_cx) / sc).round() as i16, ccx);
            try_snap_y(((ccy - base_cy) / sc).round() as i16, ccy);

            let left_margin = (ccx - chw) + pad;
            try_snap_x((((left_margin + cur_hw) - base_cx) / sc).round() as i16, left_margin);

            let right_margin = (ccx + chw) - pad;
            try_snap_x((((right_margin - cur_hw) - base_cx) / sc).round() as i16, right_margin);

            let top_margin = (ccy - chh) + pad;
            try_snap_y((((top_margin + cur_hh) - base_cy) / sc).round() as i16, top_margin);

            let bot_margin = (ccy + chh) - pad;
            try_snap_y((((bot_margin - cur_hh) - base_cy) / sc).round() as i16, bot_margin);
        }

        // 3. Snap to Sibling Element Centers and Baseline/Edges
        for i in 0..n {
            if i == elem_idx || i == card_idx {
                continue;
            }
            let bs = boxes[i];
            if !bs.visible || bs.elem_hidden {
                continue;
            }
            let scx = bs.cx / u;
            let scy = bs.cy / u;
            let shw = bs.tr_half_w / u;
            let shh = bs.tr_half_h / u;

            try_snap_x(((scx - base_cx) / sc).round() as i16, scx);
            try_snap_y(((scy - base_cy) / sc).round() as i16, scy);

            let sib_left = scx - shw;
            try_snap_x((((sib_left + cur_hw) - base_cx) / sc).round() as i16, sib_left);
            let sib_right = scx + shw;
            try_snap_x((((sib_right - cur_hw) - base_cx) / sc).round() as i16, sib_right);

            let sib_top = scy - shh;
            try_snap_y((((sib_top + cur_hh) - base_cy) / sc).round() as i16, sib_top);
            let sib_bot = scy + shh;
            try_snap_y((((sib_bot - cur_hh) - base_cy) / sc).round() as i16, sib_bot);
        }
    }

    (best_dx, best_dy, snap_line_x, snap_line_y)
}

