    fn wheel_view_key(&self) -> u32 {
        match self.active_tab {
            StudioTab::Taskbar => 10 + (self.taskbar_page as u32),
            StudioTab::DesktopWidgets => match self.widget_page {
                WidgetPage::Gallery => 20,
                WidgetPage::DateTimeThemes => 21,
                WidgetPage::MusicThemes => 22,
                WidgetPage::CustomizeApps => 23,
                WidgetPage::PickInstalledApp => 24,
                WidgetPage::PickClockFont => 25,
                WidgetPage::AppsThemes => 26,
                WidgetPage::VitalsThemes => 27,
                WidgetPage::CcThemes => 28,
                WidgetPage::ExtThemes(id) => 100 + (id.idx() as u32),
                _ => 29,
            },
            StudioTab::Wallpaper => 30,
            StudioTab::SuiteGallery => 40 + (self.suite_gallery_page as u32),
            StudioTab::Settings => 50,
        }
    }

    /// Accumulates Win32 `WM_MOUSEWHEEL` deltas (`WHEEL_DELTA = 120`) with direction-flip reset,
    /// stale-momentum decay, and page/row pacing so trackpads and mouse wheels never jump multiple
    /// pages or skip rows per notch.
    /// Returns `-1` for scroll-down / next page, `+1` for scroll-up / prev page, or `0` while accumulating.
    fn consume_wheel_step(&mut self, delta: i16, cooldown_ms: u64) -> i32 {
        let d = delta as i32;
        if d == 0 {
            return 0;
        }
        let now = Instant::now();
        let view_key = self.wheel_view_key();
        let stale = self
            .wheel_last_event_at
            .map(|t| now.duration_since(t) > Duration::from_millis(450))
            .unwrap_or(true);
        if view_key != self.wheel_last_view
            || stale
            || (self.wheel_accum != 0 && self.wheel_accum.signum() != d.signum())
        {
            self.wheel_accum = 0;
            self.wheel_last_view = view_key;
        }
        self.wheel_last_event_at = Some(now);
        self.wheel_accum = (self.wheel_accum + d).clamp(-240, 240);
        if self.wheel_accum.abs() < 120 {
            return 0;
        }
        if cooldown_ms > 0 {
            if let Some(last) = self.wheel_last_page_at {
                if now.duration_since(last) < Duration::from_millis(cooldown_ms) {
                    // Absorb excess high-frequency inertia during the cooldown window
                    self.wheel_accum = 0;
                    return 0;
                }
            }
            let dir = if self.wheel_accum > 0 { 1 } else { -1 };
            self.wheel_accum = 0;
            self.wheel_last_page_at = Some(now);
            return dir;
        }
        let dir = if self.wheel_accum > 0 { 1 } else { -1 };
        self.wheel_accum %= 120;
        dir
    }

    fn apply_mouse_wheel_delta(&mut self, delta: i16) -> bool {
        if self.active_tab == StudioTab::Taskbar && self.taskbar_page == TaskbarPage::Themes {
            let step = self.consume_wheel_step(delta, 180);
            let list = TaskbarTheme::in_folder(self.tb_folder);
            let max_page = list.len().saturating_sub(1) / 6;
            if step < 0 && self.tb_theme_page < max_page {
                self.tb_theme_page += 1;
                return true;
            } else if step > 0 && self.tb_theme_page > 0 {
                self.tb_theme_page -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::DesktopWidgets
            && self.widget_page == WidgetPage::DateTimeThemes
        {
            let step = self.consume_wheel_step(delta, 180);
            let list = ClockStyle::in_folder(self.clock_folder);
            let max_page = list.len().saturating_sub(1) / 6;
            if step < 0 && self.clock_theme_page < max_page {
                self.clock_theme_page += 1;
                return true;
            } else if step > 0 && self.clock_theme_page > 0 {
                self.clock_theme_page -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::DesktopWidgets
            && self.widget_page == WidgetPage::MusicThemes
        {
            let step = self.consume_wheel_step(delta, 180);
            let list = MusicStyle::in_folder(self.music_folder);
            let max_page = list.len().saturating_sub(1) / 6;
            if step < 0 && self.music_theme_page < max_page {
                self.music_theme_page += 1;
                return true;
            } else if step > 0 && self.music_theme_page > 0 {
                self.music_theme_page -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::DesktopWidgets
            && self.widget_page == WidgetPage::AppsThemes
        {
            let step = self.consume_wheel_step(delta, 180);
            let list = apps_styles_in_folder(self.apps_folder);
            let max_page = list.len().saturating_sub(1) / 6;
            if step < 0 && self.apps_theme_page < max_page {
                self.apps_theme_page += 1;
                return true;
            } else if step > 0 && self.apps_theme_page > 0 {
                self.apps_theme_page -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::DesktopWidgets
            && self.widget_page == WidgetPage::VitalsThemes
        {
            let step = self.consume_wheel_step(delta, 180);
            let list = vitals_styles_in_folder(self.vitals_folder);
            let max_page = list.len().saturating_sub(1) / 6;
            if step < 0 && self.vitals_theme_page < max_page {
                self.vitals_theme_page += 1;
                return true;
            } else if step > 0 && self.vitals_theme_page > 0 {
                self.vitals_theme_page -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::DesktopWidgets
            && self.widget_page == WidgetPage::CcThemes
        {
            let step = self.consume_wheel_step(delta, 180);
            let list = cc_styles_in_folder(self.cc_folder);
            let max_page = list.len().saturating_sub(1) / 6;
            if step < 0 && self.cc_theme_page < max_page {
                self.cc_theme_page += 1;
                return true;
            } else if step > 0 && self.cc_theme_page > 0 {
                self.cc_theme_page -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::DesktopWidgets
            && matches!(self.widget_page, WidgetPage::ExtThemes(_))
        {
            let step = self.consume_wheel_step(delta, 180);
            let list = ExtWidgetTheme::in_folder(self.ext_folder);
            let max_page = list.len().saturating_sub(1) / 6;
            if step < 0 && self.ext_theme_page < max_page {
                self.ext_theme_page += 1;
                return true;
            } else if step > 0 && self.ext_theme_page > 0 {
                self.ext_theme_page -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::DesktopWidgets
            && self.widget_page == WidgetPage::Gallery
        {
            let step = self.consume_wheel_step(delta, 180);
            let (_, _, p, max_p) = self.gallery_view_info();
            if step < 0 && p < max_p {
                self.gallery_page = p + 1;
                return true;
            } else if step > 0 && p > 0 {
                self.gallery_page = p - 1;
                return true;
            }
        } else if self.active_tab == StudioTab::DesktopWidgets
            && self.widget_page == WidgetPage::CustomizeApps
        {
            let step = self.consume_wheel_step(delta, 75);
            let max_scroll = self.draft_cfg.apps.len().saturating_sub(3);
            if step < 0 && self.apps_scroll < max_scroll {
                self.apps_scroll += 1;
                return true;
            } else if step > 0 && self.apps_scroll > 0 {
                self.apps_scroll -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::DesktopWidgets
            && self.widget_page == WidgetPage::PickInstalledApp
        {
            let step = self.consume_wheel_step(delta, 70);
            let filtered_len =
                filter_installed_indices(&self.installed_apps, &self.app_search_query).len();
            let max_rows = filtered_len.div_ceil(2).saturating_sub(5);
            if step < 0 && self.installed_scroll < max_rows {
                self.installed_scroll += 1;
                return true;
            } else if step > 0 && self.installed_scroll > 0 {
                self.installed_scroll -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::DesktopWidgets
            && self.widget_page == WidgetPage::PickClockFont
        {
            let step = self.consume_wheel_step(delta, 70);
            let filtered_len = self.filtered_font_indices().len();
            let max_rows = filtered_len.div_ceil(2).saturating_sub(4);
            if step < 0 && self.font_scroll < max_rows {
                self.font_scroll += 1;
                return true;
            } else if step > 0 && self.font_scroll > 0 {
                self.font_scroll -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::Wallpaper {
            let step = self.consume_wheel_step(delta, 75);
            let max_scroll = self.wallpaper_presets.len().saturating_sub(4);
            if step < 0 && self.wallpaper_scroll < max_scroll {
                self.wallpaper_scroll += 1;
                return true;
            } else if step > 0 && self.wallpaper_scroll > 0 {
                self.wallpaper_scroll -= 1;
                return true;
            }
        } else if self.active_tab == StudioTab::SuiteGallery
            && self.suite_gallery_page == SuiteGalleryPage::Collection
        {
            let step = self.consume_wheel_step(delta, 180);
            let list = suites_in_category(self.suite_cat);
            let max_page = list.len().saturating_sub(1) / 6;
            if step < 0 && self.suite_page < max_page {
                self.suite_page += 1;
                return true;
            } else if step > 0 && self.suite_page > 0 {
                self.suite_page -= 1;
                return true;
            }
        }
        false
    }

    fn gallery_view_info(&self) -> (bool, Vec<ExtWidgetId>, usize, usize) {
        match self.gallery_cat {
            GalleryCategory::CoreMedia => (true, Vec::new(), 0, 0),
            GalleryCategory::All => {
                let max_p = 1 + (ExtWidgetId::ALL.len().saturating_sub(1) / 4);
                let p = self.gallery_page.min(max_p);
                if p == 0 {
                    (true, Vec::new(), 0, max_p)
                } else {
                    let slice: Vec<ExtWidgetId> = ExtWidgetId::ALL
                        .iter()
                        .copied()
                        .skip((p - 1) * 4)
                        .take(4)
                        .collect();
                    (false, slice, p, max_p)
                }
            }
            cat => {
                let filtered: Vec<ExtWidgetId> = ExtWidgetId::ALL
                    .iter()
                    .copied()
                    .filter(|id| id.category() == cat)
                    .collect();
                let max_p = filtered.len().saturating_sub(1) / 4;
                let p = self.gallery_page.min(max_p);
                let slice = filtered.into_iter().skip(p * 4).take(4).collect();
                (false, slice, p, max_p)
            }
        }
    }

    pub fn refresh_win_prefs(&mut self) {
        self.win_prefs = read_win_taskbar_prefs();
        if !self.hwnd.0.is_null() && unsafe { IsWindowVisible(self.hwnd).as_bool() } {
            unsafe {
                let _ = InvalidateRect(Some(self.hwnd), None, false);
            }
        }
    }

    pub fn hwnd(&self) -> HWND {
        self.hwnd
    }

    pub fn is_visible(&self) -> bool {
        !self.hwnd.0.is_null()
            && unsafe { IsWindowVisible(self.hwnd).as_bool() && !IsIconic(self.hwnd).as_bool() }
    }

    /// True only when Studio is visible and either foreground or actively hovered by the cursor.
    /// Background / covered Studio windows pause preview animation timers (0% CPU).
    pub fn is_actively_viewed(&self) -> bool {
        self.is_visible()
            && (self.tb_mouse_logic.is_some()
                || unsafe { GetForegroundWindow() == self.hwnd })
    }

    pub fn is_wallpaper_tab_visible(&self) -> bool {
        self.is_visible() && self.active_tab == StudioTab::Wallpaper
    }

    pub fn wants_fast_30fps_anim(&self) -> bool {
        if !self.is_visible() {
            return false;
        }
        if is_mouse_over_interactive_preview_pos(
            self.active_tab,
            self.taskbar_page,
            self.widget_page,
            self.tb_mouse_logic,
        ) {
            return true;
        }
        // Keep 30 FPS briefly while a click-triggered preview ripple is decaying
        let tb_rip = self.active_tab == StudioTab::Taskbar
            && self
                .tb_preview_sims
                .as_ref()
                .map(|b| b.iter().any(|s| s.ripples.iter().any(|r| r.active)))
                .unwrap_or(false);
        let w_rip = self.active_tab == StudioTab::DesktopWidgets
            && (self
                .widget_preview_sims
                .as_ref()
                .map(|b| b.iter().any(|s| s.ripples.iter().any(|r| r.active)))
                .unwrap_or(false)
                || self
                    .ext_theme_sims
                    .as_ref()
                    .map(|b| b.iter().any(|s| s.ripples.iter().any(|r| r.active)))
                    .unwrap_or(false));
        tb_rip || w_rip
    }

    pub fn mark_diagnostics_exported(&mut self) {
        self.export_flash_until = Some(Instant::now() + std::time::Duration::from_secs(3));
        if self.is_visible() {
            unsafe {
                let _ = InvalidateRect(Some(self.hwnd), None, false);
            }
        }
    }

    fn export_flash_active(&self) -> bool {
        self.export_flash_until
            .map(|t| Instant::now() < t)
            .unwrap_or(false)
    }

    pub fn sync_weather_preview(&mut self, city: String, temp_c: f32, cond: &'static str) {
        let changed = self.weather_preview_city != city
            || (self.weather_preview_temp_c - temp_c).abs() >= 0.4
            || self.weather_preview_cond != cond;
        self.weather_preview_city = city;
        self.weather_preview_temp_c = temp_c;
        self.weather_preview_cond = cond;
        if changed && self.is_visible() && self.onboarding_active && self.onboarding_step == 2 {
            unsafe {
                let _ = InvalidateRect(Some(self.hwnd), None, false);
            }
        }
    }

    pub fn sync_tap_fallback_status(&mut self, fallback: bool) {
        if self.tap_fallback_active != fallback {
            self.tap_fallback_active = fallback;
            if self.is_visible() && self.active_tab == StudioTab::Taskbar {
                unsafe {
                    let _ = InvalidateRect(Some(self.hwnd), None, false);
                }
            }
        }
    }

    /// Updates live clock & telemetry preview inside Studio once per second when visible.
    pub fn tick_preview_ext(&mut self, telemetry_ext: (f32, f32, f32, f32, f32)) {
        let prev = self.telemetry_ext;
        self.telemetry = (telemetry_ext.0, telemetry_ext.2, telemetry_ext.4);
        self.telemetry_ext = telemetry_ext;
        if self.is_visible() && self.active_tab == StudioTab::DesktopWidgets {
            static LAST_CLOCK_MIN: std::sync::atomic::AtomicU64 =
                std::sync::atomic::AtomicU64::new(0);
            let now_min = std::time::SystemTime::now()
                .duration_since(std::time::UNIX_EPOCH)
                .map(|d| d.as_secs() / 60)
                .unwrap_or(0);
            let min_changed =
                LAST_CLOCK_MIN.swap(now_min, std::sync::atomic::Ordering::Relaxed) != now_min;
            let tel_changed = (prev.0.round() as i32) != (telemetry_ext.0.round() as i32)
                || (prev.1.round() as i32) != (telemetry_ext.1.round() as i32)
                || (prev.2.round() as i32) != (telemetry_ext.2.round() as i32)
                || (prev.3.round() as i32) != (telemetry_ext.3.round() as i32)
                || (prev.4.round() as i32) != (telemetry_ext.4.round() as i32);
            if (tel_changed || min_changed) && !self.is_widgets_anim_visible() {
                unsafe {
                    let _ = InvalidateRect(Some(self.hwnd), None, false);
                }
            }
        }
    }

    pub fn sync_wallpaper_decode_mode(&mut self, mode: VideoDecodeMode) {
        if self.wallpaper_decode_mode != mode {
            self.wallpaper_decode_mode = mode;
            if self.is_visible() && self.active_tab == StudioTab::Wallpaper {
                unsafe {
                    let _ = InvalidateRect(Some(self.hwnd), None, false);
                }
            }
        }
    }

    pub fn sync_live_state(
        &mut self,
        media: MediaSnapshot,
        cc: CcSnapshot,
        bands: [f32; 12],
        wp_status: &str,
        lively: bool,
    ) {
        let prev_bands = self.preview_bands;
        let wp_changed = self.wallpaper_status != wp_status || self.lively_running != lively;
        let media_changed = self.preview_media.cover_seq != media.cover_seq
            || self.preview_media.is_playing != media.is_playing
            || self.preview_media.title != media.title
            || self.preview_media.artist != media.artist
            || self.preview_cc.vol_pct != cc.vol_pct
            || self.preview_cc.bright_pct != cc.bright_pct
            || self.preview_cc.wifi_on != cc.wifi_on
            || self.preview_cc.bt_on != cc.bt_on;
        let audio_active =
            bands.iter().any(|&b| b > 0.015) || prev_bands.iter().any(|&b| b > 0.015);
        self.preview_media = media;
        self.preview_cc = cc;
        self.preview_bands = bands;
        self.wallpaper_status = wp_status.to_string();
        self.lively_running = lively;
        if self.is_visible() {
            let need_repaint = match self.active_tab {
                StudioTab::Taskbar => {
                    audio_active
                        && matches!(self.taskbar_page, TaskbarPage::Folders | TaskbarPage::Themes)
                }
                StudioTab::DesktopWidgets => {
                    media_changed
                        || (audio_active
                            && matches!(
                                self.widget_page,
                                WidgetPage::Gallery
                                    | WidgetPage::MusicFolders
                                    | WidgetPage::MusicThemes
                                    | WidgetPage::CustomizeMusic
                                    | WidgetPage::EditWidgetCanvas(WidgetCanvasTarget::Music)
                            ))
                }
                StudioTab::Wallpaper => wp_changed,
                StudioTab::SuiteGallery | StudioTab::Settings => false,
            };
            if need_repaint {
                unsafe {
                    let _ = InvalidateRect(Some(self.hwnd), None, false);
                }
            }
        }
    }

    /// Lightweight audio-band refresh used by `TIMER_VIZ_TICK` so Studio avoids cloning media
    /// snapshots, querying weather, or scanning Lively processes on every visualizer frame.
    pub fn sync_audio_bands_only(&mut self, bands: [f32; 12]) {
        if !self.is_visible() {
            return;
        }
        let shows_audio = match self.active_tab {
            StudioTab::Taskbar => {
                matches!(
                    self.taskbar_page,
                    TaskbarPage::Folders | TaskbarPage::Themes | TaskbarPage::Customize
                )
            }
            StudioTab::DesktopWidgets => matches!(
                self.widget_page,
                WidgetPage::Gallery
                    | WidgetPage::MusicFolders
                    | WidgetPage::MusicThemes
                    | WidgetPage::CustomizeMusic
                    | WidgetPage::EditWidgetCanvas(WidgetCanvasTarget::Music)
            ),
            StudioTab::Wallpaper | StudioTab::SuiteGallery | StudioTab::Settings => false,
        };
        if !shows_audio {
            return;
        }
        let max_diff = bands
            .iter()
            .zip(self.preview_bands.iter())
            .fold(0.0f32, |acc, (&a, &b)| acc.max((a - b).abs()));
        self.preview_bands = bands;
        if max_diff >= 0.004 {
            unsafe {
                let _ = InvalidateRect(Some(self.hwnd), None, false);
            }
        }
    }

    pub fn is_taskbar_themes_visible(&self) -> bool {
        self.is_actively_viewed()
            && self.active_tab == StudioTab::Taskbar
            && (matches!(self.taskbar_page, TaskbarPage::Folders | TaskbarPage::Themes)
                || (self.taskbar_page == TaskbarPage::Customize
                    && self.draft_cfg.tb_theme.uses_virtual_dock()))
    }

    pub fn is_widgets_anim_visible(&self) -> bool {
        self.is_actively_viewed()
            && self.active_tab == StudioTab::DesktopWidgets
            && self.wants_widgets_anim_page()
    }

    pub fn wants_widgets_anim_page(&self) -> bool {
        if self.active_tab != StudioTab::DesktopWidgets {
            return false;
        }
        match self.widget_page {
            WidgetPage::ExtFolders(_)
            | WidgetPage::ExtThemes(_)
            | WidgetPage::DateTimeFolders
            | WidgetPage::DateTimeThemes
            | WidgetPage::AppsFolders
            | WidgetPage::AppsThemes
            | WidgetPage::VitalsFolders
            | WidgetPage::VitalsThemes
            | WidgetPage::MusicFolders
            | WidgetPage::MusicThemes
            | WidgetPage::CcFolders
            | WidgetPage::CcThemes => true,
            WidgetPage::CustomizeDateTime => {
                self.draft_cfg.dt_hover_fx.is_interactive()
                    || self.draft_cfg.dt_style == ClockStyle::FlipMech
                    || self.draft_cfg.dt_style.is_realistic_interactive()
            }
            WidgetPage::CustomizeMusic => {
                self.draft_cfg.music_hover_fx.is_interactive()
                    || self.draft_cfg.music_style.is_realistic_interactive()
            }
            WidgetPage::CustomizeApps => {
                self.draft_cfg.apps_hover_fx.is_interactive()
                    || apps_style_horology(self.draft_cfg.apps_tile_shape)
                        .map(|h| h.has_idle_motion())
                        .unwrap_or(false)
            }
            WidgetPage::CustomizeVitals => {
                self.draft_cfg.vitals_hover_fx.is_interactive()
                    || vitals_style_horology(self.draft_cfg.vitals_style)
                        .map(|h| h.has_idle_motion())
                        .unwrap_or(false)
            }
            WidgetPage::CustomizeControlCenter => {
                self.draft_cfg.cc_hover_fx.is_interactive()
                    || cc_style_horology(self.draft_cfg.cc_tile_style)
                        .map(|h| h.has_idle_motion())
                        .unwrap_or(false)
            }
            WidgetPage::CustomizeExt(id) => {
                let ec = &self.draft_cfg.ext_widgets[id.idx()];
                ec.hover_fx.is_interactive() || ec.theme.is_realistic_interactive()
            }
            WidgetPage::EditWidgetCanvas(target) => match target {
                WidgetCanvasTarget::DateTime => {
                    self.draft_cfg.dt_hover_fx.is_interactive()
                        || self.draft_cfg.dt_style == ClockStyle::FlipMech
                        || self.draft_cfg.dt_style.is_realistic_interactive()
                }
                WidgetCanvasTarget::Apps => self.draft_cfg.apps_hover_fx.is_interactive(),
                WidgetCanvasTarget::Vitals => self.draft_cfg.vitals_hover_fx.is_interactive(),
                WidgetCanvasTarget::Music => {
                    self.draft_cfg.music_hover_fx.is_interactive()
                        || self.draft_cfg.music_style.is_realistic_interactive()
                }
                WidgetCanvasTarget::ControlCenter => self.draft_cfg.cc_hover_fx.is_interactive(),
                WidgetCanvasTarget::Ext(id) => {
                    let ec = &self.draft_cfg.ext_widgets[id.idx()];
                    ec.hover_fx.is_interactive() || ec.theme.is_realistic_interactive()
                }
            },
            WidgetPage::Gallery => {
                if !self.draft_cfg.widgets_live_material {
                    return false;
                }
                let (is_core, ext_slice, _, _) = self.gallery_view_info();
                if is_core {
                    self.draft_cfg.dt_hover_fx.is_interactive()
                        || self.draft_cfg.dt_style.has_idle_motion()
                        || self.draft_cfg.apps_hover_fx.is_interactive()
                        || self.draft_cfg.vitals_hover_fx.is_interactive()
                        || self.draft_cfg.music_hover_fx.is_interactive()
                        || self.draft_cfg.music_style.has_idle_motion()
                        || self.draft_cfg.cc_hover_fx.is_interactive()
                } else {
                    ext_slice.iter().any(|id| {
                        let ec = &self.draft_cfg.ext_widgets[id.idx()];
                        ec.hover_fx.is_interactive() || ec.theme.has_idle_motion()
                    })
                }
            }
            _ => false,
        }
    }

    pub fn tick_widgets_anim(&mut self) {
        if !self.is_widgets_anim_visible() {
            return;
        }
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_widget_anim_tick);
        if !self.wants_fast_30fps_anim() && elapsed < Duration::from_millis(85) {
            return;
        }
        let dt = elapsed.as_secs_f32().clamp(0.008, 0.11);
        self.last_widget_anim_tick = now;
        self.step_widget_preview_sims(dt);
        unsafe {
            let _ = InvalidateRect(Some(self.hwnd), None, false);
        }
    }

    fn widget_sim(&self, idx: usize) -> Option<&VizSnapshot> {
        self.widget_preview_sims.as_ref().and_then(|b| b.get(idx))
    }

    fn ext_theme_sim(&self, theme: ExtWidgetTheme) -> Option<&VizSnapshot> {
        let idx = ExtWidgetTheme::ALL.iter().position(|&t| t == theme)?;
        self.ext_theme_sims.as_ref().map(|b| &b[idx])
    }

    fn step_widget_preview_sims(&mut self, dt: f32) {
        let mpos = self.tb_mouse_logic;
        let u = self.u.max(0.5);
        let hover_react = self.draft_cfg.widgets_hover_react;

        let step_in_rect = |sim: &mut VizSnapshot,
                            fx: TaskbarVizStyle,
                            always_material: bool,
                            rbox: (f32, f32, f32, f32)| {
            if !fx.is_interactive() && !always_material {
                return;
            }
            let mut hover_in = false;
            let mut nx = 0.5;
            let mut ny = 0.5;
            if let Some((mx, my)) = mpos {
                if mx >= rbox.0
                    && mx <= rbox.0 + rbox.2
                    && my >= rbox.1
                    && my <= rbox.1 + rbox.3
                {
                    hover_in = true;
                    nx = ((mx - rbox.0) / rbox.2).clamp(0.0, 1.0);
                    ny = ((my - rbox.1) / rbox.3).clamp(0.0, 1.0);
                }
            }
            if fx.is_interactive() {
                sim.step_hover_physics(fx, dt, nx, ny, hover_in, hover_react, rbox.2 * u, rbox.3 * u);
            } else {
                sim.step_material_interactive(dt, nx, ny, hover_in, hover_react, true);
            }
        };

        match self.widget_page {
            WidgetPage::ExtFolders(_) => {
                let esims = self
                    .ext_theme_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                for th in [
                    ExtWidgetTheme::CrystalWater,
                    ExtWidgetTheme::WinterSnow,
                    ExtWidgetTheme::HearthFire,
                ] {
                    if let Some(idx) = ExtWidgetTheme::ALL.iter().position(|&t| t == th) {
                        let rbox = match th {
                            ExtWidgetTheme::CrystalWater => (26.0, 280.0, 346.0, 138.0),
                            _ => (388.0, 280.0, 346.0, 138.0),
                        };
                        step_in_rect(
                            &mut esims[idx],
                            th.hover_fx_preset(),
                            th.is_realistic_interactive(),
                            rbox,
                        );
                    }
                }
            }
            WidgetPage::ExtThemes(_) => {
                let esims = self
                    .ext_theme_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                let list = ExtWidgetTheme::in_folder(self.ext_folder);
                let max_p = list.len().saturating_sub(1) / 6;
                let page = self.ext_theme_page.min(max_p);
                for (i, &theme) in list.iter().skip(page * 6).take(6).enumerate() {
                    if let Some(idx) = ExtWidgetTheme::ALL.iter().position(|&t| t == theme) {
                        let col = i % 2;
                        let row = i / 2;
                        let x0 = if col == 0 { 26.0 } else { 386.0 };
                        let y0 = 136.0 + (row as f32) * 144.0;
                        step_in_rect(
                            &mut esims[idx],
                            theme.hover_fx_preset(),
                            theme.is_realistic_interactive(),
                            (x0 + 8.0, y0 + 6.0, 332.0, 86.0),
                        );
                    }
                }
            }
            WidgetPage::Gallery => {
                let (is_core, ext_slice, _, _) = self.gallery_view_info();
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                if is_core {
                    step_in_rect(
                        &mut wsims[0],
                        self.draft_cfg.dt_hover_fx,
                        self.draft_cfg.dt_style.is_realistic_interactive(),
                        (36.0, 132.0, 328.0, 104.0),
                    );
                    step_in_rect(&mut wsims[4], self.draft_cfg.cc_hover_fx, false, (396.0, 132.0, 328.0, 104.0));
                    step_in_rect(&mut wsims[1], self.draft_cfg.apps_hover_fx, false, (36.0, 306.0, 328.0, 74.0));
                    step_in_rect(
                        &mut wsims[3],
                        self.draft_cfg.music_hover_fx,
                        self.draft_cfg.music_style.is_realistic_interactive(),
                        (396.0, 306.0, 328.0, 74.0),
                    );
                    step_in_rect(&mut wsims[2], self.draft_cfg.vitals_hover_fx, false, (36.0, 450.0, 408.0, 110.0));
                } else {
                    for (i, id) in ext_slice.into_iter().enumerate() {
                        let col = i % 2;
                        let row = i / 2;
                        let x0 = if col == 0 { 26.0 } else { 386.0 };
                        let y0 = 124.0 + (row as f32) * 224.0;
                        let ec = &self.draft_cfg.ext_widgets[id.idx()];
                        step_in_rect(
                            &mut wsims[5 + id.idx()],
                            ec.hover_fx,
                            ec.theme.is_realistic_interactive(),
                            (x0 + 10.0, y0 + 8.0, 328.0, 152.0),
                        );
                    }
                }
            }
            WidgetPage::DateTimeFolders | WidgetPage::DateTimeThemes => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                step_in_rect(&mut wsims[0], self.draft_cfg.dt_hover_fx, true, (26.0, 136.0, 708.0, 430.0));
            }
            WidgetPage::MusicFolders | WidgetPage::MusicThemes => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                step_in_rect(&mut wsims[3], self.draft_cfg.music_hover_fx, true, (26.0, 136.0, 708.0, 430.0));
            }
            WidgetPage::AppsFolders | WidgetPage::AppsThemes => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                step_in_rect(&mut wsims[1], self.draft_cfg.apps_hover_fx, true, (26.0, 136.0, 708.0, 430.0));
            }
            WidgetPage::VitalsFolders | WidgetPage::VitalsThemes => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                step_in_rect(&mut wsims[2], self.draft_cfg.vitals_hover_fx, true, (26.0, 136.0, 708.0, 430.0));
            }
            WidgetPage::CcFolders | WidgetPage::CcThemes => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                step_in_rect(&mut wsims[4], self.draft_cfg.cc_hover_fx, true, (26.0, 136.0, 708.0, 430.0));
            }
            WidgetPage::CustomizeDateTime => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                step_in_rect(
                    &mut wsims[0],
                    self.draft_cfg.dt_hover_fx,
                    self.draft_cfg.dt_style.is_realistic_interactive(),
                    (26.0, 138.0, 708.0, 160.0),
                );
            }
            WidgetPage::CustomizeApps => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                step_in_rect(&mut wsims[1], self.draft_cfg.apps_hover_fx, false, (26.0, 140.0, 708.0, 116.0));
            }
            WidgetPage::CustomizeVitals => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                step_in_rect(&mut wsims[2], self.draft_cfg.vitals_hover_fx, false, (26.0, 140.0, 708.0, 138.0));
            }
            WidgetPage::CustomizeMusic => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                step_in_rect(
                    &mut wsims[3],
                    self.draft_cfg.music_hover_fx,
                    self.draft_cfg.music_style.is_realistic_interactive(),
                    (26.0, 140.0, 708.0, 158.0),
                );
            }
            WidgetPage::CustomizeControlCenter => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                step_in_rect(&mut wsims[4], self.draft_cfg.cc_hover_fx, false, (26.0, 140.0, 708.0, 198.0));
            }
            WidgetPage::CustomizeExt(id) => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                let ec = &self.draft_cfg.ext_widgets[id.idx()];
                step_in_rect(
                    &mut wsims[5 + id.idx()],
                    ec.hover_fx,
                    ec.theme.is_realistic_interactive(),
                    (26.0, 138.0, 708.0, 158.0),
                );
            }
            WidgetPage::EditWidgetCanvas(target) => {
                let wsims = self
                    .widget_preview_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                let (slot, fx, always_mat) = match target {
                    WidgetCanvasTarget::DateTime => (
                        0,
                        self.draft_cfg.dt_hover_fx,
                        self.draft_cfg.dt_style.is_realistic_interactive(),
                    ),
                    WidgetCanvasTarget::Apps => (1, self.draft_cfg.apps_hover_fx, false),
                    WidgetCanvasTarget::Vitals => (2, self.draft_cfg.vitals_hover_fx, false),
                    WidgetCanvasTarget::Music => (
                        3,
                        self.draft_cfg.music_hover_fx,
                        self.draft_cfg.music_style.is_realistic_interactive(),
                    ),
                    WidgetCanvasTarget::ControlCenter => (4, self.draft_cfg.cc_hover_fx, false),
                    WidgetCanvasTarget::Ext(id) => {
                        let ec = &self.draft_cfg.ext_widgets[id.idx()];
                        (5 + id.idx(), ec.hover_fx, ec.theme.is_realistic_interactive())
                    }
                };
                step_in_rect(&mut wsims[slot], fx, always_mat, (26.0, 138.0, 708.0, 216.0));
            }
            _ => {}
        }
    }

    fn trigger_preview_material_impulse(&mut self, px: f32, py: f32) {
        let hit_in = |r: (f32, f32, f32, f32)| -> Option<(f32, f32)> {
            if px >= r.0 && px <= r.0 + r.2 && py >= r.1 && py <= r.1 + r.3 {
                Some((
                    ((px - r.0) / r.2).clamp(0.05, 0.95),
                    ((py - r.1) / r.3).clamp(0.05, 0.95),
                ))
            } else {
                None
            }
        };

        if self.active_tab == StudioTab::Taskbar && self.taskbar_page == TaskbarPage::Themes {
            let list = TaskbarTheme::in_folder(self.tb_folder);
            let max_page = list.len().saturating_sub(1) / 6;
            let page = self.tb_theme_page.min(max_page);
            let sims = self
                .tb_preview_sims
                .get_or_insert_with(|| Box::new([VizSnapshot::default(); TaskbarTheme::ALL.len()]));
            for (i, &theme) in list.iter().skip(page * 6).take(6).enumerate() {
                let col = i % 2;
                let row = i / 2;
                let x0 = 26.0 + (col as f32) * 362.0;
                let y0 = 136.0 + (row as f32) * 146.0;
                if let Some((nx, ny)) = hit_in((x0, y0, 346.0, 136.0)) {
                    if let Some(idx) = TaskbarTheme::ALL.iter().position(|&t| t == theme) {
                        sims[idx].spawn_impulse(nx, ny, 1.25, 1.3);
                    }
                }
            }
            return;
        }

        if self.active_tab != StudioTab::DesktopWidgets {
            return;
        }
        match self.widget_page {
            WidgetPage::CustomizeDateTime => {
                if let Some((nx, ny)) = hit_in((26.0, 138.0, 708.0, 160.0)) {
                    let wsims = self
                        .widget_preview_sims
                        .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                    wsims[0].spawn_impulse(nx, ny, 1.25, 1.35);
                }
            }
            WidgetPage::CustomizeMusic => {
                if let Some((nx, ny)) = hit_in((26.0, 140.0, 708.0, 158.0)) {
                    let wsims = self
                        .widget_preview_sims
                        .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                    wsims[3].spawn_impulse(nx, ny, 1.25, 1.35);
                }
            }
            WidgetPage::CustomizeExt(id) => {
                if let Some((nx, ny)) = hit_in((26.0, 138.0, 708.0, 158.0)) {
                    let wsims = self
                        .widget_preview_sims
                        .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                    wsims[5 + id.idx()].spawn_impulse(nx, ny, 1.25, 1.35);
                }
            }
            WidgetPage::EditWidgetCanvas(target) => {
                if let Some((nx, ny)) = hit_in((26.0, 138.0, 708.0, 216.0)) {
                    let wsims = self
                        .widget_preview_sims
                        .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                    let slot = match target {
                        WidgetCanvasTarget::DateTime => 0,
                        WidgetCanvasTarget::Apps => 1,
                        WidgetCanvasTarget::Vitals => 2,
                        WidgetCanvasTarget::Music => 3,
                        WidgetCanvasTarget::ControlCenter => 4,
                        WidgetCanvasTarget::Ext(id) => 5 + id.idx(),
                    };
                    wsims[slot].spawn_impulse(nx, ny, 1.20, 1.35);
                }
            }
            WidgetPage::ExtThemes(_) => {
                let list = ExtWidgetTheme::in_folder(self.ext_folder);
                let max_p = list.len().saturating_sub(1) / 6;
                let page = self.ext_theme_page.min(max_p);
                let esims = self
                    .ext_theme_sims
                    .get_or_insert_with(|| Box::new(std::array::from_fn(|_| VizSnapshot::default())));
                for (i, &theme) in list.iter().skip(page * 6).take(6).enumerate() {
                    let col = i % 2;
                    let row = i / 2;
                    let x0 = if col == 0 { 26.0 } else { 386.0 };
                    let y0 = 136.0 + (row as f32) * 144.0;
                    if let Some((nx, ny)) = hit_in((x0 + 8.0, y0 + 6.0, 332.0, 86.0)) {
                        if let Some(idx) = ExtWidgetTheme::ALL.iter().position(|&t| t == theme) {
                            esims[idx].spawn_impulse(nx, ny, 1.25, 1.3);
                        }
                    }
                }
            }
            _ => {}
        }
    }

    pub fn tick_taskbar_anim(&mut self) {
        if !self.is_taskbar_themes_visible() {
            return;
        }
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_tb_anim_time);
        if !self.wants_fast_30fps_anim() && elapsed < Duration::from_millis(85) {
            return;
        }
        let dt = elapsed.as_secs_f32().clamp(0.008, 0.11);
        self.last_tb_anim_time = now;
        self.tb_anim_phase = (self.tb_anim_phase + dt * 4.5) % 1000.0;
        self.step_taskbar_preview_sims(dt);
        unsafe {
            let _ = InvalidateRect(Some(self.hwnd), None, false);
        }
    }

    fn preview_sim_for(&self, theme: TaskbarTheme) -> Option<&VizSnapshot> {
        let idx = TaskbarTheme::ALL.iter().position(|&t| t == theme)?;
        self.tb_preview_sims.as_ref().map(|b| &b[idx])
    }

    fn step_taskbar_preview_sims(&mut self, dt: f32) {
        // Pass raw live preview_bands (zeros when silent) so update_from_raw(..., true) runs smooth
        // animated idle waves when silent and switches seamlessly to real WASAPI bands when audio plays!
        let live_bands = self.preview_bands;
        let mpos = self.tb_mouse_logic;
        let u = self.u;
        let sims = self
            .tb_preview_sims
            .get_or_insert_with(|| Box::new([VizSnapshot::default(); TaskbarTheme::ALL.len()]));

        let step_one = |sims: &mut [VizSnapshot; TaskbarTheme::ALL.len()],
                        theme: TaskbarTheme,
                        hover_rect: (f32, f32, f32, f32),
                        pv_rect: (f32, f32, f32, f32)| {
            if let Some(idx) = TaskbarTheme::ALL.iter().position(|&t| t == theme) {
                let (_, _, _, _, viz_style, _) = theme.preview_preset();
                let mut hover_in = false;
                let mut nx = 0.5;
                let mut ny = 0.5;
                if let Some((mx, my)) = mpos {
                    if mx >= hover_rect.0
                        && mx <= hover_rect.0 + hover_rect.2
                        && my >= hover_rect.1
                        && my <= hover_rect.1 + hover_rect.3
                    {
                        hover_in = true;
                        nx = ((mx - pv_rect.0) / pv_rect.2).clamp(0.0, 1.0);
                        let cap_top = pv_rect.1 + pv_rect.3 - 31.0;
                        ny = ((my - cap_top) / 26.0).clamp(0.08, 0.92);
                    }
                }
                let sim = &mut sims[idx];
                sim.update_from_raw(&live_bands, dt, true);
                if viz_style.is_interactive() {
                    sim.step_hover_physics(
                        viz_style,
                        dt,
                        nx,
                        ny,
                        hover_in,
                        true,
                        pv_rect.2 * u,
                        26.0 * u,
                    );
                } else if crate::dock_themes::dock_spec(theme).art.pbr_material().is_some() {
                    sim.step_material_interactive(dt, nx, ny, hover_in, true, true);
                }
            }
        };

        match self.taskbar_page {
            TaskbarPage::Folders => {
                for (i, &folder) in TaskbarThemeFolder::CURATED.iter().enumerate() {
                    let (_, _, sample_th) = folder.card_meta();
                    let list = TaskbarTheme::in_folder(folder);
                    let preview_th = if list.contains(&self.draft_cfg.tb_theme) {
                        self.draft_cfg.tb_theme
                    } else {
                        sample_th
                    };
                    let (x0, y0, x1, y1) = tb_folder_card_rect(i);
                    let w = x1 - x0;
                    step_one(
                        sims,
                        preview_th,
                        (x0, y0, w, y1 - y0),
                        (x0 + 18.0, y0 + 29.0, w - 36.0, 53.0),
                    );
                }
            }
            TaskbarPage::Themes => {
                let list = TaskbarTheme::in_folder(self.tb_folder);
                let max_page = list.len().saturating_sub(1) / 6;
                let page = self.tb_theme_page.min(max_page);
                for (i, &theme) in list.iter().skip(page * 6).take(6).enumerate() {
                    let col = i % 2;
                    let row = i / 2;
                    let x0 = 26.0 + (col as f32) * 362.0;
                    let y0 = 136.0 + (row as f32) * 146.0;
                    step_one(sims, theme, (x0, y0, 346.0, 136.0), (x0 + 10.0, y0 + 8.0, 326.0, 74.0));
                }
            }
            TaskbarPage::Customize => {
                if self.draft_cfg.tb_theme.uses_virtual_dock() {
                    step_one(
                        sims,
                        self.draft_cfg.tb_theme,
                        (26.0, 132.0, 708.0, 84.0),
                        (26.0, 132.0, 708.0, 84.0),
                    );
                }
            }
        }
    }

    fn sync_taskbar_folder_to_active(&mut self, theme: TaskbarTheme) {
        if let Some(&folder) = TaskbarThemeFolder::CURATED
            .iter()
            .find(|&&f| TaskbarTheme::in_folder(f).contains(&theme))
        {
            self.tb_folder = folder;
            self.tb_theme_page = TaskbarTheme::in_folder(folder)
                .iter()
                .position(|&t| t == theme)
                .map(|idx| idx / 6)
                .unwrap_or(0);
        }
    }

    pub fn sync_from_config(&mut self, cfg: &AppConfig) {
        self.draft_cfg = cfg.clone();
        self.draft_initialized = true;
        if self.is_in_customize_editor() {
            self.customize_baseline = self.current_widget_canvas_target().map(|t| (t, cfg.clone()));
        } else {
            self.customize_baseline = None;
        }
        self.footer_discard_visible.set(false);
        let max_scroll = self.draft_cfg.apps.len().saturating_sub(3);
        if self.apps_scroll > max_scroll {
            self.apps_scroll = max_scroll;
        }
        if !self.hwnd.0.is_null() && unsafe { IsWindowVisible(self.hwnd).as_bool() } {
            unsafe {
                let _ = InvalidateRect(Some(self.hwnd), None, false);
            }
        }
    }

    /// Repaints the Settings window in-place (e.g. when live wallpaper color swatches update)
    /// without resetting `self.draft_cfg` or reverting any in-progress user selection.
    pub fn invalidate_redraw(&self) {
        if !self.hwnd.0.is_null() && unsafe { IsWindowVisible(self.hwnd).as_bool() } {
            unsafe {
                let _ = InvalidateRect(Some(self.hwnd), None, false);
            }
        }
    }

    pub fn sync_cached_wallpaper_path(&mut self, old_path: &str, new_path: &str) {
        if new_path.is_empty() {
            return;
        }
        if self.draft_cfg.wallpaper_path.eq_ignore_ascii_case(old_path) {
            self.draft_cfg.wallpaper_path = new_path.to_string();
        }
        for preset in &mut self.wallpaper_presets {
            if preset.path.eq_ignore_ascii_case(old_path) {
                preset.path = new_path.to_string();
            }
        }
        // Deduplicate gallery cards if the cached destination path already existed in the list.
        let mut seen: Vec<String> = Vec::with_capacity(self.wallpaper_presets.len());
        self.wallpaper_presets.retain(|p| {
            let key = p.path.to_ascii_lowercase();
            if seen.contains(&key) {
                false
            } else {
                seen.push(key);
                true
            }
        });
        let max_scroll = self.wallpaper_presets.len().saturating_sub(4);
        if self.wallpaper_scroll > max_scroll {
            self.wallpaper_scroll = max_scroll;
        }
        self.invalidate_redraw();
    }

    fn prepend_browsed_wallpaper(&mut self, path: &str) {
        if path.is_empty() {
            return;
        }
        if let Some(pos) = self
            .wallpaper_presets
            .iter()
            .position(|p| p.path.eq_ignore_ascii_case(path))
        {
            if pos > 0 {
                let item = self.wallpaper_presets.remove(pos);
                self.wallpaper_presets.insert(0, item);
            }
            self.wallpaper_scroll = 0;
            return;
        }
        let stem = std::path::Path::new(path)
            .file_stem()
            .and_then(|s| s.to_str())
            .unwrap_or("Selected Wallpaper")
            .replace(['-', '_'], " ");
        self.wallpaper_presets.insert(
            0,
            VideoWallpaperPreset {
                title: stem,
                path: path.to_string(),
            },
        );
        self.wallpaper_presets.truncate(24);
        self.wallpaper_scroll = 0;
    }

    fn ensure_wp_discovery_scan(&mut self, force: bool) {
        if force {
            self.wp_presets_loaded = false;
            if let Ok(mut guard) = self.wp_presets_shared.lock() {
                *guard = None;
            }
        }
        if self.wallpaper_presets.is_empty() || force {
            self.wallpaper_presets =
                discover_wallpapers_fast_local(&self.draft_cfg.wallpaper_path);
        }
        if (self.wp_presets_loaded && !force) || self.wp_presets_scanning {
            return;
        }
        self.wp_presets_scanning = true;
        let shared = Arc::clone(&self.wp_presets_shared);
        let cur_path = self.draft_cfg.wallpaper_path.clone();
        let notify_raw = self.hwnd.0 as usize;
        let _ = std::thread::Builder::new()
            .name("autumn-wp-scan".to_string())
            .spawn(move || {
                let found = discover_video_wallpapers(&cur_path);
                if let Ok(mut guard) = shared.lock() {
                    *guard = Some(found);
                }
                if notify_raw != 0 {
                    unsafe {
                        let _ = PostMessageW(
                            Some(HWND(notify_raw as *mut c_void)),
                            WM_APP_WP_LIST_READY,
                            WPARAM(0),
                            LPARAM(0),
                        );
                    }
                }
            });
    }

    fn pull_wp_discovery_scan(&mut self) -> bool {
        let ready = self
            .wp_presets_shared
            .lock()
            .ok()
            .and_then(|mut g| g.take());
        if let Some(mut list) = ready {
            // Keep currently selected draft wallpaper pinned at top if valid.
            let cur = self.draft_cfg.wallpaper_path.clone();
            if !cur.is_empty() && !list.iter().any(|p| p.path.eq_ignore_ascii_case(&cur)) {
                let stem = std::path::Path::new(&cur)
                    .file_stem()
                    .and_then(|s| s.to_str())
                    .unwrap_or("Active Wallpaper")
                    .replace(['-', '_'], " ");
                list.insert(
                    0,
                    VideoWallpaperPreset {
                        title: stem,
                        path: cur,
                    },
                );
                list.truncate(24);
            }
            self.wallpaper_presets = list;
            self.wp_presets_loaded = true;
            self.wp_presets_scanning = false;
            let max_wp = self.wallpaper_presets.len().saturating_sub(4);
            if self.wallpaper_scroll > max_wp {
                self.wallpaper_scroll = max_wp;
            }
            return true;
        }
        false
    }

    fn ensure_installed_scan(&mut self, force: bool) {
        if force {
            self.installed_loaded = false;
            self.installed_icons.invalidate();
            if let Ok(mut guard) = self.installed_shared.lock() {
                *guard = None;
            }
        }
        if (self.installed_loaded && !force) || self.installed_scanning {
            return;
        }
        self.installed_scanning = true;
        let shared = Arc::clone(&self.installed_shared);
        let hwnd_raw = self.hwnd.0 as isize;
        std::thread::spawn(move || {
            let list = enumerate_installed_apps();
            if let Ok(mut guard) = shared.lock() {
                *guard = Some(list);
            }
            if hwnd_raw != 0 {
                unsafe {
                    let _ = PostMessageW(
                        Some(HWND(hwnd_raw as *mut _)),
                        WM_APP_INSTALLED_READY,
                        WPARAM(0),
                        LPARAM(0),
                    );
                }
            }
        });
    }

    fn pull_installed_scan(&mut self) {
        if let Ok(mut guard) = self.installed_shared.lock() {
            if let Some(list) = guard.take() {
                if self.is_visible() && self.widget_page == WidgetPage::PickInstalledApp {
                    self.installed_apps = list;
                    self.installed_loaded = true;
                } else {
                    drop(list);
                    self.installed_loaded = false;
                }
                self.installed_scanning = false;
                self.installed_icons.invalidate();
                self.installed_scroll = 0;
            }
        }
    }

    pub fn open_tab(&mut self, cfg: &AppConfig, taskbar_hidden: bool, tab: StudioTab, page: WidgetPage) {
        self.active_tab = tab;
        self.widget_page = page;
        if page == WidgetPage::PickInstalledApp {
            self.pick_replace_slot = None;
            self.pick_selected_apps.clear();
            self.app_search_query.clear();
            self.app_search_focused = true;
            self.installed_scroll = 0;
        } else {
            self.app_search_focused = false;
        }
        self.open(cfg, taskbar_hidden);
        if page == WidgetPage::PickInstalledApp {
            self.ensure_installed_scan(false);
        }
    }

    pub fn open_taskbar_customize(&mut self, cfg: &AppConfig, taskbar_hidden: bool) {
        self.active_tab = StudioTab::Taskbar;
        self.taskbar_page = TaskbarPage::Customize;
        self.app_search_focused = false;
        self.open(cfg, taskbar_hidden);
    }

    fn ensure_graphics_init(&mut self) {
        if self.d2d_factory.is_none() {
            self.d2d_factory =
                unsafe { D2D1CreateFactory(D2D1_FACTORY_TYPE_SINGLE_THREADED, None).ok() };
        }
        if self.dwrite_factory.is_none() {
            self.dwrite_factory =
                unsafe { DWriteCreateFactory(DWRITE_FACTORY_TYPE_SHARED).ok() };
        }
        if self.wic_factory.is_none() {
            self.wic_factory = unsafe {
                CoCreateInstance(&CLSID_WICImagingFactory, None, CLSCTX_INPROC_SERVER).ok()
            };
        }
        if self.custom_fonts.is_none() {
            self.custom_fonts = self
                .dwrite_factory
                .as_ref()
                .and_then(|dw| unsafe { build_custom_font_collection(dw) });
        }
        if self.dc_rt.is_none() {
            self.dc_rt = self.d2d_factory.as_ref().and_then(create_settings_dc_rt);
        }
    }

    pub fn open(&mut self, cfg: &AppConfig, taskbar_hidden: bool) {
        self.onboarding_active = false;
        self.open_internal(cfg, taskbar_hidden);
    }

    pub fn open_onboarding(&mut self, cfg: &AppConfig, taskbar_hidden: bool) {
        self.onboarding_active = true;
        self.onboarding_step = 0;
        self.open_internal(cfg, taskbar_hidden);
    }

    fn open_internal(&mut self, cfg: &AppConfig, taskbar_hidden: bool) {
        self.ensure_graphics_init();
        self.taskbar_hidden = taskbar_hidden;
        self.win_prefs = read_win_taskbar_prefs();
        self.startup_on = is_startup_enabled();
        self.draft_cfg = cfg.clone();
        self.draft_initialized = true;
        self.applied_flash = false;
        self.editing_app_name = None;
        self.apps_scroll = 0;
        self.wallpaper_presets = discover_wallpapers_fast_local(&self.draft_cfg.wallpaper_path);
        self.wp_presets_loaded = false;
        self.wallpaper_scroll = 0;
        self.lively_running = is_lively_running();

        if self.hwnd.0.is_null() {
            self.create_window();
        }
        if self.active_tab == StudioTab::Wallpaper {
            self.ensure_wp_discovery_scan(false);
        }
        if !self.hwnd.0.is_null() {
            unsafe {
                let _ = ShowWindow(self.hwnd, SW_RESTORE);
                let _ = ShowWindow(self.hwnd, SW_SHOW);
                let _ = SetForegroundWindow(self.hwnd);
                let _ = InvalidateRect(Some(self.hwnd), None, false);
            }
        }
    }

    fn release_installed_picker_cache(&mut self) {
        self.installed_icons.invalidate();
        self.installed_apps.clear();
        self.installed_apps.shrink_to_fit();
        self.installed_loaded = false;
        self.pick_selected_apps.clear();
        if let Ok(mut guard) = self.installed_shared.lock() {
            *guard = None;
        }
    }

    pub fn release_idle_resources(&mut self) {
        self.res = None;
        self.preview_icons.invalidate();
        self.preview_cover.invalidate();
        self.preview_media = MediaSnapshot::default();
        if let Some(ref rt) = self.dc_rt {
            crate::realistic_pbr::evict_rt(rt);
            crate::horology_pbr::evict_rt(rt);
            crate::dock_themes::evict_luxury_hud_rt(rt);
        }
        self.dc_rt = None;
        self.backbuf.release();
        self.custom_fonts = None;
        self.dwrite_factory = None;
        self.d2d_factory = None;
        self.wic_factory = None;
        self.wallpaper_presets.clear();
        self.wallpaper_presets.shrink_to_fit();
        self.wp_presets_loaded = false;
        self.wp_presets_scanning = false;
        if let Ok(mut guard) = self.wp_presets_shared.lock() {
            *guard = None;
        }
        self.wp_thumbs.invalidate();
        self.tb_preview_sims = None;
        self.tb_mouse_logic = None;
        self.widget_preview_sims = None;
        self.ext_theme_sims = None;
        self.release_installed_picker_cache();
        crate::config::trim_process_working_set();
    }

    pub fn hide_and_release(&mut self) {
        if !self.hwnd.0.is_null() {
            unsafe {
                let _ = ShowWindow(self.hwnd, SW_HIDE);
            }
        }
        self.release_idle_resources();
    }

    pub fn sync_status_only(&mut self, _cfg: &AppConfig, taskbar_hidden: bool) {
        self.taskbar_hidden = taskbar_hidden;
        if !self.hwnd.0.is_null() && unsafe { IsWindowVisible(self.hwnd).as_bool() } {
            unsafe {
                let _ = InvalidateRect(Some(self.hwnd), None, false);
            }
        }
    }

    pub fn cleanup(&mut self) {
        self.release_idle_resources();
        unsafe {
            if !self.hwnd.0.is_null() {
                let _ = DestroyWindow(self.hwnd);
                self.hwnd = HWND::default();
            }
        }
    }

    fn create_window(&mut self) {
        unsafe {
            let hmon = MonitorFromPoint(POINT { x: 0, y: 0 }, MONITOR_DEFAULTTOPRIMARY);
            let mut mi = MONITORINFO {
                cbSize: size_of::<MONITORINFO>() as u32,
                ..Default::default()
            };
            let mon_rc = if GetMonitorInfoW(hmon, &mut mi).as_bool() {
                mi.rcMonitor
            } else {
                RECT { left: 0, top: 0, right: 1920, bottom: 1200 }
            };

            let Ok(hwnd) = CreateWindowExW(
                Default::default(),
                w!("AutumnSettingsWnd"),
                w!("AutumnDeck Studio"),
                WS_POPUP | WS_SYSMENU | WS_MINIMIZEBOX,
                100,
                100,
                800,
                600,
                None,
                None,
                Some(self.hinst),
                None,
            ) else {
                return;
            };
            self.hwnd = hwnd;

            let raw_dpi = GetDpiForWindow(hwnd);
            let dpi = if raw_dpi == 0 { 144 } else { raw_dpi };
            self.u = dpi as f32 / 96.0;
            self.win_w = (LOGICAL_W * self.u).round() as i32;
            self.win_h = (LOGICAL_H * self.u).round() as i32;

            let x = mon_rc.left + ((mon_rc.right - mon_rc.left) - self.win_w) / 2;
            let y = mon_rc.top + ((mon_rc.bottom - mon_rc.top) - self.win_h) / 2;

            let dark: i32 = 1;
            let _ = DwmSetWindowAttribute(
                hwnd,
                DWMWA_USE_IMMERSIVE_DARK_MODE,
                (&dark as *const i32) as *const _,
                4,
            );
            let round = DWMWCP_ROUND;
            let _ = DwmSetWindowAttribute(
                hwnd,
                DWMWA_WINDOW_CORNER_PREFERENCE,
                (&round as *const _) as *const _,
                4,
            );
            let border_col: u32 = 0x00243D56;
            let _ = DwmSetWindowAttribute(
                hwnd,
                DWMWA_BORDER_COLOR,
                (&border_col as *const u32) as *const _,
                4,
            );

            let _ = SetWindowPos(
                hwnd,
                Some(HWND_TOP),
                x,
                y,
                self.win_w,
                self.win_h,
                SWP_SHOWWINDOW,
            );
        }
    }

    pub fn handle_message(
        &mut self,
        hwnd: HWND,
        msg: u32,
        wparam: WPARAM,
        lparam: LPARAM,
        cfg: &mut AppConfig,
        taskbar_hidden: bool,
    ) -> Option<(LRESULT, SettingsCommand)> {
        if self.hwnd.0.is_null() || hwnd != self.hwnd {
            return None;
        }
        if !self.draft_initialized {
            self.draft_cfg = cfg.clone();
            self.draft_initialized = true;
        }
        self.taskbar_hidden = taskbar_hidden;

        match msg {
            WM_APP_INSTALLED_READY => {
                self.pull_installed_scan();
                if !self.hwnd.0.is_null() && unsafe { IsWindowVisible(self.hwnd).as_bool() } {
                    unsafe {
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                }
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_APP_WP_THUMB_READY => {
                if self.wp_thumbs.drain_ready()
                    && !self.hwnd.0.is_null()
                    && unsafe { IsWindowVisible(self.hwnd).as_bool() }
                    && self.active_tab == StudioTab::Wallpaper
                {
                    unsafe {
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                }
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_APP_WP_LIST_READY => {
                if self.pull_wp_discovery_scan()
                    && !self.hwnd.0.is_null()
                    && unsafe { IsWindowVisible(self.hwnd).as_bool() }
                    && self.active_tab == StudioTab::Wallpaper
                {
                    unsafe {
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                }
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_SIZE => {
                if wparam.0 as u32 == SIZE_MINIMIZED {
                    self.release_idle_resources();
                }
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_CLOSE => {
                self.hide_and_release();
                Some((LRESULT(0), SettingsCommand::None))
            }
            0x0002 => {
                self.hwnd = HWND::default();
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_ERASEBKGND => Some((LRESULT(1), SettingsCommand::None)),
            WM_SETCURSOR => {
                let interactive = !matches!(self.hovered, HitZone::None | HitZone::TitleDrag);
                unsafe {
                    let cur = LoadCursorW(None, if interactive { IDC_HAND } else { IDC_ARROW })
                        .unwrap_or_default();
                    SetCursor(Some(cur));
                }
                Some((LRESULT(1), SettingsCommand::None))
            }
            WM_KEYDOWN => {
                if let Some(slot) = self.editing_app_name {
                    match wparam.0 {
                        VK_RETURN_CODE | VK_ESCAPE_CODE => {
                            self.editing_app_name = None;
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                            return Some((LRESULT(0), SettingsCommand::None));
                        }
                        VK_BACK_CODE => {
                            if let Some(s) = self.slot_name_mut(slot) {
                                s.pop();
                            }
                            self.applied_flash = false;
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                            return Some((LRESULT(0), SettingsCommand::None));
                        }
                        _ => {}
                    }
                } else if self.active_tab == StudioTab::DesktopWidgets
                    && self.widget_page == WidgetPage::PickInstalledApp
                    && self.app_search_focused
                {
                    match wparam.0 {
                        VK_ESCAPE_CODE => {
                            if !self.app_search_query.is_empty() {
                                self.app_search_query.clear();
                                self.installed_scroll = 0;
                            } else {
                                self.app_search_focused = false;
                            }
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                            return Some((LRESULT(0), SettingsCommand::None));
                        }
                        VK_RETURN_CODE => {
                            self.app_search_focused = false;
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                            return Some((LRESULT(0), SettingsCommand::None));
                        }
                        VK_BACK_CODE => {
                            if self.app_search_query.pop().is_some() {
                                self.installed_scroll = 0;
                                unsafe {
                                    let _ = InvalidateRect(Some(self.hwnd), None, false);
                                }
                            }
                            return Some((LRESULT(0), SettingsCommand::None));
                        }
                        _ => {}
                    }
                } else if self.active_tab == StudioTab::DesktopWidgets
                    && self.widget_page == WidgetPage::PickClockFont
                    && self.font_search_focused
                {
                    match wparam.0 {
                        VK_ESCAPE_CODE => {
                            if !self.font_search_query.is_empty() {
                                self.font_search_query.clear();
                                self.font_scroll = 0;
                            } else {
                                self.font_search_focused = false;
                            }
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                            return Some((LRESULT(0), SettingsCommand::None));
                        }
                        VK_RETURN_CODE => {
                            self.font_search_focused = false;
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                            return Some((LRESULT(0), SettingsCommand::None));
                        }
                        VK_BACK_CODE => {
                            if self.font_search_query.pop().is_some() {
                                self.font_scroll = 0;
                                unsafe {
                                    let _ = InvalidateRect(Some(self.hwnd), None, false);
                                }
                            }
                            return Some((LRESULT(0), SettingsCommand::None));
                        }
                        _ => {}
                    }
                } else if self.active_tab == StudioTab::DesktopWidgets
                    && matches!(self.widget_page, WidgetPage::CustomizeExt(ExtWidgetId::Notes))
                    && self.editing_note_slot.is_some()
                {
                    let slot = self.editing_note_slot.unwrap();
                    match wparam.0 {
                        VK_RETURN_CODE | VK_ESCAPE_CODE => {
                            self.editing_note_slot = None;
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                            return Some((LRESULT(0), SettingsCommand::None));
                        }
                        VK_BACK_CODE => {
                            if let Some(s) = match slot {
                                usize::MAX => Some(&mut self.draft_cfg.notes_title),
                                idx => self.draft_cfg.notes_items.get_mut(idx).map(|it| &mut it.1),
                            } {
                                s.pop();
                            }
                            self.sync_canvas_target_to_live(cfg, WidgetCanvasTarget::Ext(ExtWidgetId::Notes));
                            self.applied_flash = false;
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                            return Some((LRESULT(0), SettingsCommand::WidgetsConfigUpdated));
                        }
                        _ => {}
                    }
                } else if self.active_tab == StudioTab::DesktopWidgets
                    && matches!(self.widget_page, WidgetPage::EditWidgetCanvas(_))
                {
                    let shift_held = unsafe { GetKeyState(VK_SHIFT.0 as i32) < 0 };
                    let ctrl_held = unsafe { GetKeyState(VK_CONTROL.0 as i32) < 0 };
                    if self.handle_canvas_keydown(wparam.0, shift_held, ctrl_held) {
                        self.sync_canvas_target_to_live(cfg, self.canvas_target);
                        self.applied_flash = true;
                        unsafe {
                            let _ = InvalidateRect(Some(self.hwnd), None, false);
                        }
                        return Some((LRESULT(0), SettingsCommand::WidgetsConfigUpdated));
                    }
                }
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_CHAR => {
                if let Some(slot) = self.editing_app_name {
                    let ch = (wparam.0 & 0xFFFF) as u16;
                    if ch >= 32 && ch != 127 {
                        if let Some(c) = char::from_u32(ch as u32) {
                            if let Some(s) = self.slot_name_mut(slot) {
                                if s.chars().count() < 20 {
                                    s.push(c);
                                    self.applied_flash = false;
                                }
                            }
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                        }
                    }
                    return Some((LRESULT(0), SettingsCommand::None));
                } else if self.active_tab == StudioTab::DesktopWidgets
                    && self.widget_page == WidgetPage::PickInstalledApp
                    && self.app_search_focused
                {
                    let ch = (wparam.0 & 0xFFFF) as u16;
                    if ch >= 32 && ch != 127 {
                        if let Some(c) = char::from_u32(ch as u32) {
                            if self.app_search_query.chars().count() < 40 {
                                self.app_search_query.push(c);
                                self.installed_scroll = 0;
                            }
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                        }
                    }
                    return Some((LRESULT(0), SettingsCommand::None));
                } else if self.active_tab == StudioTab::DesktopWidgets
                    && self.widget_page == WidgetPage::PickClockFont
                    && self.font_search_focused
                {
                    let ch = (wparam.0 & 0xFFFF) as u16;
                    if ch >= 32 && ch != 127 {
                        if let Some(c) = char::from_u32(ch as u32) {
                            if self.font_search_query.chars().count() < 40 {
                                self.font_search_query.push(c);
                                self.font_scroll = 0;
                            }
                            unsafe {
                                let _ = InvalidateRect(Some(self.hwnd), None, false);
                            }
                        }
                    }
                    return Some((LRESULT(0), SettingsCommand::None));
                } else if self.active_tab == StudioTab::DesktopWidgets
                    && matches!(self.widget_page, WidgetPage::CustomizeExt(ExtWidgetId::Notes))
                    && self.editing_note_slot.is_some()
                {
                    let slot = self.editing_note_slot.unwrap();
                    let ch = (wparam.0 & 0xFFFF) as u16;
                    if ch >= 32 && ch != 127 {
                        if let Some(c) = char::from_u32(ch as u32) {
                            if c != '|' {
                                let max_len = if slot == usize::MAX { 28 } else { 52 };
                                if let Some(s) = match slot {
                                    usize::MAX => Some(&mut self.draft_cfg.notes_title),
                                    idx => self.draft_cfg.notes_items.get_mut(idx).map(|it| &mut it.1),
                                } {
                                    if s.chars().count() < max_len {
                                        s.push(c);
                                        self.sync_canvas_target_to_live(cfg, WidgetCanvasTarget::Ext(ExtWidgetId::Notes));
                                        self.applied_flash = false;
                                    }
                                }
                                unsafe {
                                    let _ = InvalidateRect(Some(self.hwnd), None, false);
                                }
                                return Some((LRESULT(0), SettingsCommand::WidgetsConfigUpdated));
                            }
                        }
                    }
                    return Some((LRESULT(0), SettingsCommand::None));
                }
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_MOUSEWHEEL_MSG => {
                let delta = ((wparam.0 >> 16) & 0xFFFF) as i16;
                if self.apply_mouse_wheel_delta(delta) {
                    unsafe {
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                }
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_MOUSEMOVE => {
                if !self.tracking_mouse {
                    let mut tme = TRACKMOUSEEVENT {
                        cbSize: size_of::<TRACKMOUSEEVENT>() as u32,
                        dwFlags: TME_LEAVE,
                        hwndTrack: self.hwnd,
                        dwHoverTime: 0,
                    };
                    unsafe {
                        let _ = TrackMouseEvent(&mut tme);
                    }
                    self.tracking_mouse = true;
                }

                let px = (lparam.0 & 0xFFFF) as i16 as f32 / self.u;
                let py = ((lparam.0 >> 16) & 0xFFFF) as i16 as f32 / self.u;
                self.tb_mouse_logic = Some((px, py));

                if self.canvas_drag.is_some() {
                    self.update_canvas_drag(px, py);
                    unsafe {
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                    return Some((LRESULT(0), SettingsCommand::None));
                }

                if let Some(kind) = self.dragging_slider {
                    let raw_cmd = self
                        .update_slider_from_x(kind, px, cfg)
                        .unwrap_or(SettingsCommand::None);
                    let cmd = if matches!(
                        raw_cmd,
                        SettingsCommand::StylePreview | SettingsCommand::MacDockPreview
                    ) {
                        let now = Instant::now();
                        let allow = self
                            .last_live_preview_at
                            .map(|t| now.duration_since(t) >= Duration::from_millis(16))
                            .unwrap_or(true);
                        if allow {
                            self.last_live_preview_at = Some(now);
                            raw_cmd
                        } else {
                            SettingsCommand::None
                        }
                    } else {
                        raw_cmd
                    };
                    unsafe {
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                    return Some((LRESULT(0), cmd));
                }

                let zone = self.hit_test(px, py);
                if zone != self.hovered {
                    self.hovered = zone;
                    unsafe {
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                }
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_MOUSELEAVE_MSG => {
                self.tracking_mouse = false;
                self.tb_mouse_logic = None;
                if self.hovered != HitZone::None {
                    self.hovered = HitZone::None;
                    unsafe {
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                }
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_CAPTURECHANGED | WM_KILLFOCUS => {
                self.dragging_slider = None;
                self.canvas_drag = None;
                self.canvas_snap_lines = (None, None);
                self.pressed_zone = HitZone::None;
                Some((LRESULT(0), SettingsCommand::None))
            }
            WM_LBUTTONDOWN => {
                let px = (lparam.0 & 0xFFFF) as i16 as f32 / self.u;
                let py = ((lparam.0 >> 16) & 0xFFFF) as i16 as f32 / self.u;
                self.trigger_preview_material_impulse(px, py);

                if self.active_tab == StudioTab::DesktopWidgets
                    && matches!(self.widget_page, WidgetPage::EditWidgetCanvas(_))
                    && self.try_begin_canvas_drag(px, py)
                {
                    unsafe {
                        SetCapture(self.hwnd);
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                    return Some((LRESULT(0), SettingsCommand::None));
                }

                let zone = self.hit_test(px, py);

                if !matches!(zone, HitZone::EditAppName(_)) {
                    self.editing_app_name = None;
                }
                if !matches!(zone, HitZone::SearchInstalledFocus | HitZone::ClearSearchInstalled) {
                    self.app_search_focused = false;
                }

                match zone {
                    HitZone::TitleDrag => {
                        self.pressed_zone = HitZone::None;
                        unsafe {
                            let _ = ReleaseCapture();
                            let _ = SendMessageW(
                                self.hwnd,
                                WM_NCLBUTTONDOWN,
                                Some(WPARAM(HTCAPTION as usize)),
                                Some(LPARAM(0)),
                            );
                        }
                        Some((LRESULT(0), SettingsCommand::None))
                    }
                    HitZone::Slider(kind) => {
                        if matches!(
                            kind,
                            SliderKind::ElemScale
                                | SliderKind::ElemRot
                                | SliderKind::ElemX
                                | SliderKind::ElemY
                                | SliderKind::ElemTextSize
                                | SliderKind::ElemHue
                                | SliderKind::ElemBorderHue
                                | SliderKind::ElemGlow
                                | SliderKind::ElemBorder
                                | SliderKind::ElemGradHue
                                | SliderKind::CanvasCardGlass
                                | SliderKind::CanvasCardRadius
                        ) {
                            self.push_canvas_undo();
                        }
                        self.dragging_slider = Some(kind);
                        self.pressed_zone = zone;
                        unsafe {
                            SetCapture(self.hwnd);
                        }
                        let cmd = self
                            .update_slider_from_x(kind, px, cfg)
                            .unwrap_or(SettingsCommand::None);
                        if matches!(
                            cmd,
                            SettingsCommand::StylePreview | SettingsCommand::MacDockPreview
                        ) {
                            self.last_live_preview_at = Some(Instant::now());
                        }
                        unsafe {
                            let _ = InvalidateRect(Some(self.hwnd), None, false);
                        }
                        Some((LRESULT(0), cmd))
                    }
                    HitZone::None => {
                        self.pressed_zone = HitZone::None;
                        Some((LRESULT(0), SettingsCommand::None))
                    }
                    other => {
                        self.pressed_zone = other;
                        Some((LRESULT(0), SettingsCommand::None))
                    }
                }
            }
            WM_LBUTTONUP => {
                if self.canvas_drag.take().is_some() {
                    self.canvas_snap_lines = (None, None);
                    self.pressed_zone = HitZone::None;
                    self.sync_canvas_target_to_live(cfg, self.canvas_target);
                    self.applied_flash = true;
                    unsafe {
                        let _ = ReleaseCapture();
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                    return Some((LRESULT(0), SettingsCommand::WidgetsConfigUpdated));
                }

                if let Some(kind) = self.dragging_slider.take() {
                    self.pressed_zone = HitZone::None;
                    unsafe {
                        let _ = ReleaseCapture();
                        let _ = InvalidateRect(Some(self.hwnd), None, false);
                    }
                    let cmd = if kind == SliderKind::TaskbarOpacity
                        && cfg.tb_theme.uses_virtual_dock()
                    {
                        SettingsCommand::MacDockUpdated
                    } else if matches!(
                        kind,
                        SliderKind::TaskbarOpacity
                            | SliderKind::TbVizOpacity
                            | SliderKind::TbVizHue
                    ) {
                        SettingsCommand::StyleUpdated
                    } else if matches!(
                        kind,
                        SliderKind::MacDockIconSize
                            | SliderKind::MacDockMagPct
                            | SliderKind::MacDockShelfOpacity
                            | SliderKind::MacDockCardOpacity
                            | SliderKind::MacDockLabelFontSize
                    ) {
                        SettingsCommand::MacDockUpdated
                    } else if matches!(
                        kind,
                        SliderKind::DtScale
                            | SliderKind::DtGlass
                            | SliderKind::DtRim
                            | SliderKind::DtRadius
                            | SliderKind::DtSpacing
                            | SliderKind::DtHue
                            | SliderKind::ElemScale
                            | SliderKind::ElemRot
                            | SliderKind::ElemX
                            | SliderKind::ElemY
                            | SliderKind::ElemTextSize
                            | SliderKind::ElemHue
                            | SliderKind::ElemBorderHue
                            | SliderKind::ElemGlow
                            | SliderKind::ElemBorder
                            | SliderKind::ElemGradHue
                            | SliderKind::CanvasCardGlass
                            | SliderKind::CanvasCardRadius
                            | SliderKind::ExtScale
                            | SliderKind::ExtWidth
                            | SliderKind::ExtRadius
                            | SliderKind::ExtPadding
                            | SliderKind::ExtParam1
                            | SliderKind::ExtParam2
                            | SliderKind::ExtGlass
                            | SliderKind::ExtRim
                            | SliderKind::ExtRimWidth
                            | SliderKind::ExtFontScale
                            | SliderKind::HoroGlare
                    ) {
                        if let Some(tgt) = self.current_widget_canvas_target() {
                            self.sync_canvas_target_to_live(cfg, tgt);
                            self.applied_flash = true;
                            SettingsCommand::WidgetsConfigUpdated
                        } else {
                            SettingsCommand::None
                        }
                    } else if kind == SliderKind::WallpaperVolume {
                        cfg.wallpaper_volume_pct = self.draft_cfg.wallpaper_volume_pct;
                        self.applied_flash = true;
                        SettingsCommand::WallpaperConfigUpdated
                    } else {
                        SettingsCommand::None
                    };
                    return Some((LRESULT(0), cmd));
                }

                let pressed = self.pressed_zone;
                self.pressed_zone = HitZone::None;

                let px = (lparam.0 & 0xFFFF) as i16 as f32 / self.u;
                let py = ((lparam.0 >> 16) & 0xFFFF) as i16 as f32 / self.u;
                let zone = self.hit_test(px, py);
                let cmd = if zone == pressed && zone != HitZone::None {
                    self.activate_zone(zone, cfg)
                } else {
                    SettingsCommand::None
                };
                unsafe {
                    let _ = InvalidateRect(Some(self.hwnd), None, false);
                }
                Some((LRESULT(0), cmd))
            }
            WM_PAINT => {
                self.paint(cfg);
                Some((LRESULT(0), SettingsCommand::None))
            }
            _ => None,
        }
    }

    pub fn capture_canvas_snapshot(&self, target: WidgetCanvasTarget) -> CanvasHistoryEntry {
        let mut transforms = [ClockElemTransform::default(); 8];
        let mut fonts: [String; 8] = std::array::from_fn(|_| String::new());
        let n = target.elem_count().min(8);
        for i in 0..n {
            transforms[i] = self.draft_cfg.canvas_elem(target, i);
            fonts[i] = self.draft_cfg.canvas_elem_font(target, i).to_string();
        }
        let (card_glass, card_radius) = match target {
            WidgetCanvasTarget::DateTime => (self.draft_cfg.dt_glass_alpha, self.draft_cfg.dt_corner_radius),
            WidgetCanvasTarget::Apps => (self.draft_cfg.apps_glass_alpha, self.draft_cfg.apps_corner_radius),
            WidgetCanvasTarget::Vitals => (self.draft_cfg.vitals_glass_alpha, self.draft_cfg.vitals_corner_radius),
            WidgetCanvasTarget::Music => (self.draft_cfg.music_glass_alpha, self.draft_cfg.music_corner_radius),
            WidgetCanvasTarget::ControlCenter => (self.draft_cfg.cc_glass_alpha, self.draft_cfg.cc_corner_radius),
            WidgetCanvasTarget::Ext(id) => (
                self.draft_cfg.ext_widgets[id.idx()].glass_alpha,
                self.draft_cfg.ext_widgets[id.idx()].corner_radius,
            ),
        };
        CanvasHistoryEntry {
            target,
            transforms,
            fonts,
            card_glass,
            card_radius,
        }
    }

    pub fn apply_canvas_snapshot(&mut self, snap: &CanvasHistoryEntry) {
        let n = snap.target.elem_count().min(8);
        for i in 0..n {
            *self.draft_cfg.canvas_elem_mut(snap.target, i) = snap.transforms[i];
            *self.draft_cfg.canvas_elem_font_mut(snap.target, i) = snap.fonts[i].clone();
        }
        match snap.target {
            WidgetCanvasTarget::DateTime => {
                self.draft_cfg.dt_glass_alpha = snap.card_glass;
                self.draft_cfg.dt_corner_radius = snap.card_radius;
            }
            WidgetCanvasTarget::Apps => {
                self.draft_cfg.apps_glass_alpha = snap.card_glass;
                self.draft_cfg.apps_corner_radius = snap.card_radius;
            }
            WidgetCanvasTarget::Vitals => {
                self.draft_cfg.vitals_glass_alpha = snap.card_glass;
                self.draft_cfg.vitals_corner_radius = snap.card_radius;
            }
            WidgetCanvasTarget::Music => {
                self.draft_cfg.music_glass_alpha = snap.card_glass;
                self.draft_cfg.music_corner_radius = snap.card_radius;
            }
            WidgetCanvasTarget::ControlCenter => {
                self.draft_cfg.cc_glass_alpha = snap.card_glass;
                self.draft_cfg.cc_corner_radius = snap.card_radius;
            }
            WidgetCanvasTarget::Ext(id) => {
                self.draft_cfg.ext_widgets[id.idx()].glass_alpha = snap.card_glass;
                self.draft_cfg.ext_widgets[id.idx()].corner_radius = snap.card_radius;
            }
        }
    }

    pub fn push_canvas_undo(&mut self) {
        let snap = self.capture_canvas_snapshot(self.canvas_target);
        if self.canvas_undo_stack.last() == Some(&snap) {
            return;
        }
        if self.canvas_undo_stack.len() >= 32 {
            self.canvas_undo_stack.remove(0);
        }
        self.canvas_undo_stack.push(snap);
        self.canvas_redo_stack.clear();
    }

    pub fn undo_canvas(&mut self) -> bool {
        let Some(prev) = self.canvas_undo_stack.pop() else {
            return false;
        };
        let cur = self.capture_canvas_snapshot(prev.target);
        if self.canvas_redo_stack.len() >= 32 {
            self.canvas_redo_stack.remove(0);
        }
        self.canvas_redo_stack.push(cur);
        self.apply_canvas_snapshot(&prev);
        self.applied_flash = false;
        true
    }

    pub fn redo_canvas(&mut self) -> bool {
        let Some(next) = self.canvas_redo_stack.pop() else {
            return false;
        };
        let cur = self.capture_canvas_snapshot(next.target);
        if self.canvas_undo_stack.len() >= 32 {
            self.canvas_undo_stack.remove(0);
        }
        self.canvas_undo_stack.push(cur);
        self.apply_canvas_snapshot(&next);
        self.applied_flash = false;
        true
    }

    pub fn copy_canvas_elem_style(&mut self) {
        let tr = self.draft_cfg.canvas_elem(self.canvas_target, self.canvas_elem_idx);
        let font = self
            .draft_cfg
            .canvas_elem_font(self.canvas_target, self.canvas_elem_idx)
            .to_string();
        self.canvas_clipboard = Some(ClipboardStyle {
            font_family: font,
            font_scale_pct: tr.font_scale_pct,
            scale_pct: tr.scale_pct,
            color_rgb: tr.color_rgb,
            color2_rgb: tr.color2_rgb,
            gradient_angle: tr.gradient_angle,
            shadow_blur: tr.shadow_blur,
            glow_rgb: tr.glow_rgb,
            border_width: tr.border_width,
            border_rgb: tr.border_rgb,
        });
    }

    pub fn paste_canvas_elem_style(&mut self) -> bool {
        let Some(clip) = self.canvas_clipboard.clone() else {
            return false;
        };
        self.push_canvas_undo();
        let is_card = self.canvas_target.is_card_slot(self.canvas_elem_idx);
        {
            let slot = self
                .draft_cfg
                .canvas_elem_mut(self.canvas_target, self.canvas_elem_idx);
            slot.color_rgb = clip.color_rgb;
            slot.color2_rgb = clip.color2_rgb;
            slot.gradient_angle = clip.gradient_angle;
            slot.shadow_blur = clip.shadow_blur;
            slot.glow_rgb = clip.glow_rgb;
            slot.border_width = clip.border_width;
            slot.border_rgb = clip.border_rgb;
            if !is_card {
                slot.font_scale_pct = clip.font_scale_pct;
            }
        }
        if !is_card {
            *self
                .draft_cfg
                .canvas_elem_font_mut(self.canvas_target, self.canvas_elem_idx) = clip.font_family;
        }
        self.applied_flash = false;
        true
    }

    pub fn handle_canvas_keydown(&mut self, vk: usize, shift_held: bool, ctrl_held: bool) -> bool {
        if self.active_tab != StudioTab::DesktopWidgets
            || !matches!(self.widget_page, WidgetPage::EditWidgetCanvas(_))
        {
            return false;
        }
        if ctrl_held {
            return match vk {
                0x5A => self.undo_canvas(),
                0x59 => self.redo_canvas(),
                0x43 => {
                    self.copy_canvas_elem_style();
                    true
                }
                0x56 => self.paste_canvas_elem_style(),
                _ => false,
            };
        }
        let step: i16 = if shift_held { 10 } else { 1 };
        match vk {
            0x25 => {
                self.push_canvas_undo();
                let slot = self.draft_cfg.canvas_elem_mut(self.canvas_target, self.canvas_elem_idx);
                slot.dx = (slot.dx - step).clamp(-280, 280);
                self.applied_flash = false;
                true
            }
            0x27 => {
                self.push_canvas_undo();
                let slot = self.draft_cfg.canvas_elem_mut(self.canvas_target, self.canvas_elem_idx);
                slot.dx = (slot.dx + step).clamp(-280, 280);
                self.applied_flash = false;
                true
            }
            0x26 => {
                self.push_canvas_undo();
                let slot = self.draft_cfg.canvas_elem_mut(self.canvas_target, self.canvas_elem_idx);
                slot.dy = (slot.dy - step).clamp(-180, 180);
                self.applied_flash = false;
                true
            }
            0x28 => {
                self.push_canvas_undo();
                let slot = self.draft_cfg.canvas_elem_mut(self.canvas_target, self.canvas_elem_idx);
                slot.dy = (slot.dy + step).clamp(-180, 180);
                self.applied_flash = false;
                true
            }
            0xDB => {
                self.push_canvas_undo();
                let slot = self.draft_cfg.canvas_elem_mut(self.canvas_target, self.canvas_elem_idx);
                slot.scale_pct = slot.scale_pct.saturating_sub(5).clamp(35, 260);
                self.applied_flash = false;
                true
            }
            0xDD => {
                self.push_canvas_undo();
                let slot = self.draft_cfg.canvas_elem_mut(self.canvas_target, self.canvas_elem_idx);
                slot.scale_pct = (slot.scale_pct + 5).clamp(35, 260);
                self.applied_flash = false;
                true
            }
            0x52 => {
                self.push_canvas_undo();
                let slot = self.draft_cfg.canvas_elem_mut(self.canvas_target, self.canvas_elem_idx);
                let d_rot = if shift_held { 5 } else { -5 };
                slot.rot_deg = (slot.rot_deg + d_rot).clamp(-180, 180);
                self.applied_flash = false;
                true
            }
            0x2E | 0x08 => {
                self.push_canvas_undo();
                let slot = self.draft_cfg.canvas_elem_mut(self.canvas_target, self.canvas_elem_idx);
                slot.visible = false;
                self.applied_flash = false;
                true
            }
            _ => false,
        }
    }

    fn slot_name_mut(&mut self, slot: usize) -> Option<&mut String> {
        self.draft_cfg.apps.get_mut(slot).map(|a| &mut a.name)
    }

    fn picker_remaining_slots(&self) -> usize {
        12usize.saturating_sub(self.draft_cfg.apps.len())
    }

    fn selected_app_pos(&self, path: &str) -> Option<usize> {
        self.pick_selected_apps
            .iter()
            .position(|(_, p)| p.eq_ignore_ascii_case(path))
    }

    fn toggle_selected_app(&mut self, name: String, path: String) -> bool {
        if self
            .draft_cfg
            .apps
            .iter()
            .any(|a| a.path.eq_ignore_ascii_case(&path))
        {
            return false;
        }
        if let Some(pos) = self.selected_app_pos(&path) {
            self.pick_selected_apps.remove(pos);
            return true;
        }
        if self.pick_selected_apps.len() < self.picker_remaining_slots() {
            self.pick_selected_apps.push((name, path));
            return true;
        }
        false
    }

    fn commit_selected_apps(&mut self, cfg: &mut AppConfig) -> usize {
        let pending = std::mem::take(&mut self.pick_selected_apps);
        let mut added = 0usize;
        for (name, path) in pending {
            if self.draft_cfg.apps.len() >= 12 {
                break;
            }
            if self
                .draft_cfg
                .apps
                .iter()
                .any(|a| a.path.eq_ignore_ascii_case(&path))
            {
                continue;
            }
            self.draft_cfg.apps.push(AppShortcut {
                name,
                path,
                offset_x: 0,
                offset_y: 0,
            });
            added += 1;
        }
        if added > 0 {
            self.apps_scroll = self.draft_cfg.apps.len().saturating_sub(3);
            self.preview_icons.invalidate();
            self.sync_canvas_target_to_live(cfg, WidgetCanvasTarget::Apps);
            self.applied_flash = true;
        }
        self.app_search_focused = false;
        self.widget_page = WidgetPage::CustomizeApps;
        self.release_installed_picker_cache();
        added
    }

    fn apply_chosen_app(&mut self, name: String, path: String, cfg: &mut AppConfig) -> bool {
        let mut changed = false;
        if let Some(slot) = self.pick_replace_slot.take() {
            if slot < self.draft_cfg.apps.len() {
                let prev = &self.draft_cfg.apps[slot];
                self.draft_cfg.apps[slot] = AppShortcut {
                    name,
                    path,
                    offset_x: prev.offset_x,
                    offset_y: prev.offset_y,
                };
                self.preview_icons.invalidate();
                self.sync_canvas_target_to_live(cfg, WidgetCanvasTarget::Apps);
                self.applied_flash = true;
                changed = true;
            }
        } else if self.draft_cfg.apps.len() < 12
            && !self
                .draft_cfg
                .apps
                .iter()
                .any(|a| a.path.eq_ignore_ascii_case(&path))
        {
            self.draft_cfg.apps.push(AppShortcut {
                name,
                path,
                offset_x: 0,
                offset_y: 0,
            });
            self.apps_scroll = self.draft_cfg.apps.len().saturating_sub(3);
            self.preview_icons.invalidate();
            self.sync_canvas_target_to_live(cfg, WidgetCanvasTarget::Apps);
            self.applied_flash = true;
            changed = true;
        }
        self.app_search_focused = false;
        self.widget_page = WidgetPage::CustomizeApps;
        self.release_installed_picker_cache();
        changed
    }

    fn customize_apps_preview_layout(&self) -> (f32, f32, f32, Vec<(f32, f32)>, Option<(f32, f32)>) {
        let n = self.draft_cfg.apps.len();
        let show_add = self.draft_cfg.apps_show_add_tile && n < 12;
        let total_tiles = n + usize::from(show_add);
        let cols = self.draft_cfg.apps_cols.max(1) as usize;
        let (offsets, total_w, total_h) = apps_layout_offsets(total_tiles.max(1), cols);
        let sf = (668.0 / total_w).min(100.0 / total_h).min(0.95);
        let ax0 = 380.0 - (total_w * sf) * 0.5;
        let ay0 = 198.0 - (total_h * sf) * 0.5;
        let add_rel = if show_add { Some(offsets[n]) } else { None };
        let app_offsets = offsets.into_iter().take(n).collect();
        (ax0, ay0, sf, app_offsets, add_rel)
    }

    fn current_widget_canvas_target(&self) -> Option<WidgetCanvasTarget> {
        match self.widget_page {
            WidgetPage::DateTimeFolders
            | WidgetPage::DateTimeThemes
            | WidgetPage::CustomizeDateTime => Some(WidgetCanvasTarget::DateTime),
            WidgetPage::AppsFolders
            | WidgetPage::AppsThemes
            | WidgetPage::CustomizeApps
            | WidgetPage::PickInstalledApp => {
                Some(WidgetCanvasTarget::Apps)
            }
            WidgetPage::VitalsFolders
            | WidgetPage::VitalsThemes
            | WidgetPage::CustomizeVitals => Some(WidgetCanvasTarget::Vitals),
            WidgetPage::MusicFolders
            | WidgetPage::MusicThemes
            | WidgetPage::CustomizeMusic => Some(WidgetCanvasTarget::Music),
            WidgetPage::CcFolders
            | WidgetPage::CcThemes
            | WidgetPage::CustomizeControlCenter => Some(WidgetCanvasTarget::ControlCenter),
            WidgetPage::ExtFolders(id)
            | WidgetPage::ExtThemes(id)
            | WidgetPage::CustomizeExt(id) => Some(WidgetCanvasTarget::Ext(id)),
            WidgetPage::EditWidgetCanvas(tgt) => Some(tgt),
            WidgetPage::PickClockFont => match self.font_picker_return_page {
                WidgetPage::CustomizeDateTime => Some(WidgetCanvasTarget::DateTime),
                WidgetPage::CustomizeApps => Some(WidgetCanvasTarget::Apps),
                WidgetPage::CustomizeVitals => Some(WidgetCanvasTarget::Vitals),
                WidgetPage::CustomizeMusic => Some(WidgetCanvasTarget::Music),
                WidgetPage::CustomizeControlCenter => Some(WidgetCanvasTarget::ControlCenter),
                WidgetPage::CustomizeExt(id) => Some(WidgetCanvasTarget::Ext(id)),
                WidgetPage::EditWidgetCanvas(tgt) => Some(tgt),
                _ => None,
            },
            WidgetPage::Gallery => None,
        }
    }

    fn is_in_customize_editor(&self) -> bool {
        matches!(
            self.widget_page,
            WidgetPage::CustomizeDateTime
                | WidgetPage::CustomizeApps
                | WidgetPage::CustomizeVitals
                | WidgetPage::CustomizeMusic
                | WidgetPage::CustomizeControlCenter
                | WidgetPage::CustomizeExt(_)
                | WidgetPage::EditWidgetCanvas(_)
        )
    }

    fn canvas_target_differs(a: &AppConfig, b: &AppConfig, target: WidgetCanvasTarget) -> bool {
        let mut pa = AppConfig::default();
        let mut pb = AppConfig::default();
        Self::copy_canvas_target_config(a, &mut pa, target);
        Self::copy_canvas_target_config(b, &mut pb, target);
        pa != pb
    }

    fn has_customize_session_changes(&self) -> bool {
        if let Some((tgt, ref base)) = self.customize_baseline {
            if self.current_widget_canvas_target() == Some(tgt) {
                return Self::canvas_target_differs(&self.draft_cfg, base, tgt);
            }
        }
        false
    }

    fn hit_test_custom_footer(&self, x: f32, y: f32) -> Option<HitZone> {
        if in_rect(x, y, 26.0, 584.0, 146.0, 622.0) {
            return Some(HitZone::BtnResetWidget);
        }
        if (self.footer_discard_visible.get() || self.has_customize_session_changes())
            && in_rect(x, y, 154.0, 584.0, 248.0, 622.0)
        {
            return Some(HitZone::BtnDiscardWidget);
        }
        if in_rect(x, y, 422.0, 584.0, 546.0, 622.0) {
            return Some(HitZone::BtnBackGallery);
        }
        if in_rect(x, y, 558.0, 584.0, 734.0, 622.0) {
            return Some(HitZone::BtnApplyWidgets);
        }
        None
    }

