                rt.DrawRoundedRectangle(&q_rr, if q_hov { &r.coral } else { &r.card_border }, 1.0 * u, None);
                draw_txt(rt, "Exit", &r.tf_btn, q_rr.rect, if q_hov { &r.dark_ink } else { &r.cream });
