    #[test]
    fn verify_hover_options_and_idle_cpu_gating() {
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }

        // 1. User toggles roundtrip cleanly through INI save/load
        let mut cfg = AppConfig::default();
        cfg.tb_hover_react = false;
        cfg.tb_ambient_anim = false;
        cfg.widgets_hover_react = false;
        cfg.widgets_live_material = false;
        let ini = crate::config::serialize_config_ini(&cfg);
        let parsed = crate::config::parse_config_ini(&ini).expect("parse_config_ini");
        assert!(!parsed.tb_hover_react);
        assert!(!parsed.tb_ambient_anim);
        assert!(!parsed.widgets_hover_react);
        assert!(!parsed.widgets_live_material);

        // 2. Idle static tactile PBR themes (Saddle Leather, Brushed Titanium, Walnut Brass) burn 0 FPS
        let sims: [VizSnapshot; 19] = std::array::from_fn(|_| VizSnapshot::default());
        let mut leather_cfg = AppConfig::default();
        leather_cfg.apply_clock_style_preset(ClockStyle::LeatherFieldClock);
        leather_cfg.apply_music_style_preset(MusicStyle::LeatherFieldAudio);
        leather_cfg.ext_widgets[ExtWidgetId::Notes.idx()].enabled = true;
        leather_cfg.ext_widgets[ExtWidgetId::Notes.idx()].theme = ExtWidgetTheme::SaddleLeather;
        leather_cfg.ext_widgets[ExtWidgetId::Calendar.idx()].enabled = true;
        leather_cfg.ext_widgets[ExtWidgetId::Calendar.idx()].theme = ExtWidgetTheme::SaddleLeather;
        assert!(
            !crate::desktop_widgets::widgets_want_viz_tick(&leather_cfg, &sims, false, false),
            "Static tactile PBR suite must stay at 0 FPS when idle"
        );
        // Active hover or impulse wakes cleanly when widgets_hover_react = true
        assert!(
            crate::desktop_widgets::widgets_want_viz_tick(&leather_cfg, &sims, true, false),
            "Active cursor movement over PBR widget must animate when widgets_hover_react = true"
        );
        leather_cfg.widgets_hover_react = false;
        assert!(
            !crate::desktop_widgets::widgets_want_viz_tick(&leather_cfg, &sims, true, false),
            "Hover reactions must stay disabled when widgets_hover_react = false"
        );

        // 3. Fluid atmospheric PBR themes honor widgets_live_material toggle
        let mut ocean_cfg = AppConfig::default();
        ocean_cfg.apply_clock_style_preset(ClockStyle::WaterCausticsClock);
        assert!(
            crate::desktop_widgets::widgets_want_viz_tick(&ocean_cfg, &sims, false, false),
            "Ocean Lagoon caustics animate continuously when widgets_live_material = true"
        );
        ocean_cfg.widgets_live_material = false;
        assert!(
            !crate::desktop_widgets::widgets_want_viz_tick(&ocean_cfg, &sims, false, false),
            "Turning off widgets_live_material stops ambient 30 FPS widget loops"
        );

        // 4. Dock ambient gating respects static materials & user tb_ambient_anim flag
        let mut dock_cfg = AppConfig::default();
        dock_cfg.apply_taskbar_theme_preset(TaskbarTheme::SaddleLeatherDock);
        assert!(
            !crate::dock_themes::is_ambient_animated_cfg(&dock_cfg),
            "Static SaddleLeatherDock must not force 30 FPS idle dock ticks"
        );
        dock_cfg.apply_taskbar_theme_preset(TaskbarTheme::OceanTideDock);
        assert!(crate::dock_themes::is_ambient_animated_cfg(&dock_cfg));
        dock_cfg.tb_ambient_anim = false;
        assert!(
            !crate::dock_themes::is_ambient_animated_cfg(&dock_cfg),
            "tb_ambient_anim = false must silence dock ambient animation"
        );

        // 5. Studio UI hit-tests & activations for MacDock + Standard Taskbar + Widgets Gallery
        let mut sc = SettingsController::new(HINSTANCE::default());
        let mut live_cfg = AppConfig::default();
        live_cfg.apply_taskbar_theme_preset(TaskbarTheme::AbyssalTrenchDock);
        sc.draft_cfg = live_cfg.clone();

        sc.active_tab = StudioTab::Taskbar;
        sc.taskbar_page = TaskbarPage::Customize;
        sc.dock_custom_tab = DockCustomTab::LayoutHide;
        let hz_hover = sc.hit_test(200.0, 542.0);
        let hz_live = sc.hit_test(540.0, 542.0);
        assert_eq!(hz_hover, HitZone::ToggleTbHoverReact);
        assert_eq!(hz_live, HitZone::ToggleTbAmbientAnim);
        let cmd1 = sc.activate_zone(hz_hover, &mut live_cfg);
        assert!(matches!(cmd1, SettingsCommand::StyleUpdated));
        assert!(!live_cfg.tb_hover_react);
        let cmd2 = sc.activate_zone(hz_live, &mut live_cfg);
        assert!(matches!(cmd2, SettingsCommand::StyleUpdated));
        assert!(!live_cfg.tb_ambient_anim);

        sc.active_tab = StudioTab::DesktopWidgets;
        sc.widget_page = WidgetPage::Gallery;
        let hz_wh = sc.hit_test(400.0, 603.0);
        let hz_wl = sc.hit_test(520.0, 603.0);
        assert_eq!(hz_wh, HitZone::ToggleWidgetsHoverReact);
        assert_eq!(hz_wl, HitZone::ToggleWidgetsLiveMaterial);
        let cmd3 = sc.activate_zone(hz_wh, &mut live_cfg);
        assert!(matches!(cmd3, SettingsCommand::WidgetsConfigUpdated));
        assert!(!live_cfg.widgets_hover_react);
        let cmd4 = sc.activate_zone(hz_wl, &mut live_cfg);
        assert!(matches!(cmd4, SettingsCommand::WidgetsConfigUpdated));
        assert!(!live_cfg.widgets_live_material);

        // Verify negative feedback loop doesn't freeze step_material_interactive when off
        let mut sim = VizSnapshot::default();
        assert!(!sim.step_material_interactive(0.033, 0.5, 0.5, true, false, true));
        assert!(!sim.is_active());

        // 6. Verify widget hover-leave animation never lags or freezes stuck:
        //    (a) Ambient live elemental widget FX (HoverSakura / HoverFire / AuroraFlow) keeps ticking after mouse leaves
        let mut sakura_cfg = AppConfig::default();
        sakura_cfg.dt_hover_fx = TaskbarVizStyle::HoverSakura;
        assert!(
            crate::desktop_widgets::widgets_want_viz_tick(&sakura_cfg, &sims, false, false),
            "Elemental hover FX must stay smoothly animated after mouse leaves when widgets_live_material = true"
        );
        sakura_cfg.widgets_live_material = false;
        assert!(
            !crate::desktop_widgets::widgets_want_viz_tick(&sakura_cfg, &sims, false, false),
            "Turning off widgets_live_material stops idle elemental loops cleanly"
        );

        //    (b) On mouse leave, hover_mix decays smoothly all the way to exact 0.0 (no stuck residue)
        //        and click ripples on non-water styles (HoverSnow / AmbientGlow) expire cleanly
        let mut fx_sim = VizSnapshot::default();
        fx_sim.spawn_impulse(0.5, 0.5, 1.0, 0.45);
        for _ in 0..8 {
            fx_sim.step_hover_physics(TaskbarVizStyle::HoverSnow, 0.033, 0.5, 0.5, true, true, 360.0, 140.0);
        }
        assert!(fx_sim.hover_mix > 0.8);
        for _ in 0..40 {
            fx_sim.step_hover_physics(TaskbarVizStyle::HoverSnow, 0.033, 0.5, 0.5, false, true, 360.0, 140.0);
        }
        assert_eq!(fx_sim.hover_mix, 0.0, "hover_mix must settle to exact 0.0 on mouse leave");
        assert!(!fx_sim.is_active(), "HoverSnow sim and click ripple must retire cleanly after leave");

        let mut pbr_sim = VizSnapshot::default();
        for _ in 0..8 {
            pbr_sim.step_material_interactive(0.033, 0.4, 0.4, true, true, false);
        }
        assert!(pbr_sim.hover_mix > 0.8);
        for _ in 0..30 {
            pbr_sim.step_material_interactive(0.033, 0.4, 0.4, false, true, false);
        }
        assert_eq!(pbr_sim.hover_mix, 0.0, "PBR hover_mix must settle to exact 0.0 on mouse leave");
        assert!(!pbr_sim.is_active());

        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

