    #[test]
    fn settings_page_startup_export_import_and_header_gear() {
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }
        let mut sc = SettingsController::new(HINSTANCE::default());
        sc.win_w = 760;
        sc.win_h = 640;
        sc.u = 1.0;
        sc.ensure_graphics_init();
        assert!(sc.backbuf.ensure_size(760, 640));

        let mut cfg = AppConfig::default();
        sc.draft_cfg = cfg.clone();
        sc.active_tab = StudioTab::Wallpaper;

        // 1. Clicking header gear opens Settings and remembers previous tab; clicking again returns
        assert_eq!(sc.hit_test(640.0, 29.0), HitZone::TabSettings);
        sc.activate_zone(HitZone::TabSettings, &mut cfg);
        assert_eq!(sc.active_tab, StudioTab::Settings);
        assert_eq!(sc.prev_non_settings_tab, StudioTab::Wallpaper);
        assert!(sc.render_d2d(&cfg), "Settings tab must render cleanly in Direct2D");

        // 2. Verify all App Settings controls hit-test accurately (Backup/Export/Import removed)
        assert_eq!(sc.hit_test(200.0, 154.0), HitZone::ToggleStartup);
        assert_eq!(sc.hit_test(150.0, 202.0), HitZone::ToggleGameModePause);
        assert_eq!(sc.hit_test(380.0, 202.0), HitZone::ToggleWidgetsLock);
        assert_eq!(sc.hit_test(610.0, 202.0), HitZone::ToggleWidgets24h);
        for (idx, expected_fps) in [(0u8, 24u32), (1, 30), (2, 45), (3, 60), (4, 90)] {
            let (bx0, by0, bx1, by1) = anim_fps_preset_rect(idx as usize);
            assert_eq!(
                sc.hit_test((bx0 + bx1) * 0.5, (by0 + by1) * 0.5),
                HitZone::SetAnimFpsPreset(idx)
            );
            let cf = sc.activate_zone(HitZone::SetAnimFpsPreset(idx), &mut cfg);
            assert!(matches!(cf, SettingsCommand::WidgetsConfigUpdated));
            assert_eq!(cfg.anim_fps, expected_fps);
        }
        // Clicking High-Hz preset again toggles 90 -> 120 -> 90
        let _ = sc.activate_zone(HitZone::SetAnimFpsPreset(4), &mut cfg);
        assert_eq!(cfg.anim_fps, 120);
        let _ = sc.activate_zone(HitZone::SetAnimFpsPreset(2), &mut cfg);
        assert_eq!(cfg.anim_fps, 45);
        assert_eq!(sc.hit_test(140.0, 385.0), HitZone::BtnExportDiagnostics);
        assert_eq!(sc.hit_test(380.0, 385.0), HitZone::BtnOpenConfigFolder);
        assert_eq!(sc.hit_test(600.0, 385.0), HitZone::BtnRunOnboarding);
        assert_eq!(sc.hit_test(140.0, 445.0), HitZone::None);
        for (idx, mode) in [
            (0usize, PerformanceMode::Smooth),
            (1, PerformanceMode::Balanced),
            (2, PerformanceMode::Eco),
        ] {
            let (px0, py0, px1, py1) = perf_mode_pill_rect(idx);
            assert_eq!(
                sc.hit_test((px0 + px1) * 0.5, (py0 + py1) * 0.5),
                HitZone::SetPerformanceMode(mode)
            );
            let cp = sc.activate_zone(HitZone::SetPerformanceMode(mode), &mut cfg);
            assert!(matches!(cp, SettingsCommand::WidgetsConfigUpdated));
            assert_eq!(cfg.performance_mode, mode);
            assert_eq!(sc.draft_cfg.performance_mode, mode);
        }
        assert!(sc.render_d2d(&cfg), "Settings tab with Performance Mode selector must render cleanly");
        assert_eq!(sc.hit_test(100.0, 603.0), HitZone::BtnSettingsBack);
        assert_eq!(sc.hit_test(232.0, 603.0), HitZone::None);
        assert_eq!(sc.hit_test(391.0, 603.0), HitZone::BtnSupportKofi);
        assert_eq!(sc.hit_test(550.0, 603.0), HitZone::None);
        assert_eq!(sc.hit_test(640.0, 603.0), HitZone::BtnQuitApp);

        sc.hovered = HitZone::BtnSupportKofi;
        assert!(sc.render_d2d(&cfg), "Settings tab with hovered Ko-fi button must render cleanly");
        let kofi_cmd = sc.activate_zone(HitZone::BtnSupportKofi, &mut cfg);
        assert!(matches!(kofi_cmd, SettingsCommand::None));
        assert!(
            sc.setup_feedback
                .as_ref()
                .map(|(ok, msg)| *ok && msg.contains(KOFI_SUPPORT_URL))
                .unwrap_or(false),
            "Activating Tip on Ko-fi must set confirmation feedback"
        );
        sc.hovered = HitZone::None;

        // 3. Toggles update cfg cleanly and sync 24h clock format across widgets & dock
        let c24 = sc.activate_zone(HitZone::ToggleWidgets24h, &mut cfg);
        assert!(matches!(c24, SettingsCommand::WidgetsConfigUpdated));
        assert!(cfg.widgets_24h);
        assert_eq!(cfg.w_clock.use_24h, Some(true));
        let cgm = sc.activate_zone(HitZone::ToggleGameModePause, &mut cfg);
        assert!(matches!(cgm, SettingsCommand::GameModeUpdated));
        assert!(!cfg.game_mode_pause);

        // 4. Back returns to previous tab; Native Taskbar Customize bottom-right routes to Settings
        sc.activate_zone(HitZone::BtnSettingsBack, &mut cfg);
        assert_eq!(sc.active_tab, StudioTab::Wallpaper);
        sc.active_tab = StudioTab::Taskbar;
        sc.taskbar_page = TaskbarPage::Customize;
        cfg.tb_theme = TaskbarTheme::AutumnCrystal;
        assert_eq!(sc.hit_test(520.0, 555.0), HitZone::TabSettings);
        assert!(sc.render_d2d(&cfg), "Taskbar Customize with Settings quick link must render cleanly");

        // 5. Dock Customize: 3 clean visibility cards (NO Smart Auto-Hide!) + Modules -> Clock 12h/24h toggle (Bar OFF)
        cfg.tb_theme = TaskbarTheme::RealisticWaterDock;
        cfg.mac_dock_enabled = true;
        cfg.dock_bar_enabled = false;
        sc.draft_cfg = cfg.clone();
        sc.dock_custom_tab = DockCustomTab::LayoutHide;
        assert_eq!(sc.hit_test(140.0, 403.0), HitZone::MacDockHideBtn(MacDockHideMode::AlwaysVisible));
        assert_eq!(sc.hit_test(380.0, 403.0), HitZone::MacDockHideBtn(MacDockHideMode::HoverReveal));
        assert_eq!(sc.hit_test(620.0, 403.0), HitZone::MacDockHideBtn(MacDockHideMode::StealthHide));
        let cmd_stealth = sc.activate_zone(HitZone::MacDockHideBtn(MacDockHideMode::StealthHide), &mut cfg);
        assert!(matches!(cmd_stealth, SettingsCommand::MacDockUpdated));
        assert_eq!(cfg.mac_dock_hide, MacDockHideMode::StealthHide);
        assert_eq!(cfg.mode, TaskbarMode::StealthHide);
        sc.dock_custom_tab = DockCustomTab::Modules;
        sc.tb_widget_tab = TaskbarWidgetTab::Clock;
        assert_eq!(sc.hit_test(293.0, 356.0), HitZone::ToggleWidgets24h);
        let cmd_clk = sc.activate_zone(HitZone::ToggleWidgets24h, &mut cfg);
        assert!(matches!(cmd_clk, SettingsCommand::WidgetsConfigUpdated));
        assert!(!cfg.widgets_24h);
        assert_eq!(cfg.w_clock.use_24h, Some(false));
        assert!(sc.render_d2d(&cfg), "Dock Customize with Stealth Hide and Clock 24h toggle must render cleanly");

        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

    #[test]
    fn artistic_widget_folder_and_theme_previews_not_monochrome_yellow() {
        use windows::Win32::System::Com::{CoInitializeEx, CoUninitialize, COINIT_APARTMENTTHREADED};
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }

        // Verify Music & Clock folder label counts match exact slice lengths
        assert_eq!(MusicThemeFolder::All.label(), format!("All Music ({})", MusicStyle::ALL.len()));
        assert_eq!(
            MusicThemeFolder::GlassVinyl.label(),
            format!("Vinyl & Art ({})", MusicStyle::in_folder(MusicThemeFolder::GlassVinyl).len())
        );
        assert_eq!(
            ClockThemeFolder::Realistic.label(),
            format!("Realistic & Calm ({})", ClockStyle::in_folder(ClockThemeFolder::Realistic).len())
        );

        let mut sc = SettingsController::new(HINSTANCE::default());
        sc.win_w = 760;
        sc.win_h = 640;
        sc.u = 1.0;
        sc.ensure_graphics_init();
        assert!(sc.backbuf.ensure_size(760, 640));

        let mut cfg = AppConfig::default();
        cfg.dt_match_wallpaper = false;
        cfg.music_match_wallpaper = false;
        sc.draft_cfg = cfg.clone();
        sc.active_tab = StudioTab::DesktopWidgets;

        let dump_dir = std::env::var("AUTUMN_DUMP_ARTISTIC_PREVIEWS").ok();

        // Render Clock Folders & Theme pages
        sc.widget_page = WidgetPage::DateTimeFolders;
        assert!(sc.render_d2d(&cfg), "DateTimeFolders artistic previews must render");
        if let Some(ref dir) = dump_dir {
            dump_dib_bmp(&sc.backbuf, &std::path::Path::new(dir).join("artistic_clock_folders.bmp"));
        }
        for folder in [
            ClockThemeFolder::SignatureSerif,
            ClockThemeFolder::MinimalIsland,
            ClockThemeFolder::CyberPoster,
        ] {
            sc.clock_folder = folder;
            sc.clock_theme_page = 0;
            sc.widget_page = WidgetPage::DateTimeThemes;
            assert!(sc.render_d2d(&cfg), "DateTimeThemes {:?} must render", folder);
        }

        // Render Music Folders & Theme pages
        sc.widget_page = WidgetPage::MusicFolders;
        assert!(sc.render_d2d(&cfg), "MusicFolders artistic previews must render");
        if let Some(ref dir) = dump_dir {
            dump_dib_bmp(&sc.backbuf, &std::path::Path::new(dir).join("artistic_music_folders.bmp"));
        }
        for folder in [
            MusicThemeFolder::GlassVinyl,
            MusicThemeFolder::SpectrumEq,
            MusicThemeFolder::AnalogHardware,
        ] {
            sc.music_folder = folder;
            sc.music_theme_page = 0;
            sc.widget_page = WidgetPage::MusicThemes;
            assert!(sc.render_d2d(&cfg), "MusicThemes {:?} must render", folder);
        }

        // Render Extended Widget Folders & Themes
        sc.widget_page = WidgetPage::ExtFolders(ExtWidgetId::Weather);
        assert!(sc.render_d2d(&cfg), "ExtFolders must render");
        sc.ext_folder = ExtThemeFolder::GlassMinimal;
        sc.widget_page = WidgetPage::ExtThemes(ExtWidgetId::Weather);
        assert!(sc.render_d2d(&cfg), "ExtThemes must render");

        // Selecting a new Clock/Music theme adopts its artistic native palette while saving previous custom colors
        sc.draft_cfg.dt_style = ClockStyle::FlipMech;
        sc.draft_cfg.dt_use_custom_color = true;
        sc.draft_cfg.dt_accent_rgb = 0xE65C4F;
        let _ = sc.activate_zone(HitZone::SelectClockTheme(ClockStyle::ChronoDial), &mut cfg);
        assert!(!sc.draft_cfg.dt_use_custom_color, "Fresh theme click should use its artistic native palette");
        assert_eq!(
            resolve_clock_palette(&sc.draft_cfg).accent,
            ThemePalette::for_clock_style(ClockStyle::ChronoDial).accent
        );
        // Switching back to FlipMech restores its saved custom color
        let _ = sc.activate_zone(HitZone::SelectClockTheme(ClockStyle::FlipMech), &mut cfg);
        assert!(sc.draft_cfg.dt_use_custom_color);
        assert_eq!(sc.draft_cfg.dt_accent_rgb, 0xE65C4F);

        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

    #[test]
    fn studio_preview_fast_anim_gating_respects_preview_bounds() {
        // Unhovered Studio never requests 30 FPS
        assert!(!is_mouse_over_interactive_preview_pos(
            StudioTab::Taskbar,
            TaskbarPage::Folders,
            WidgetPage::Gallery,
            None,
        ));
        // Hovering header, tabs, or bottom Apply/Back footer does NOT wake 30 FPS
        assert!(!is_mouse_over_interactive_preview_pos(
            StudioTab::Taskbar,
            TaskbarPage::Folders,
            WidgetPage::Gallery,
            Some((200.0, 60.0)),
        ));
        assert!(!is_mouse_over_interactive_preview_pos(
            StudioTab::Taskbar,
            TaskbarPage::Themes,
            WidgetPage::Gallery,
            Some((600.0, 610.0)),
        ));
        // Hovering directly over a Taskbar folder or theme preview card DOES wake 30 FPS
        assert!(is_mouse_over_interactive_preview_pos(
            StudioTab::Taskbar,
            TaskbarPage::Folders,
            WidgetPage::Gallery,
            Some((200.0, 220.0)),
        ));
        assert!(is_mouse_over_interactive_preview_pos(
            StudioTab::Taskbar,
            TaskbarPage::Themes,
            WidgetPage::Gallery,
            Some((450.0, 340.0)),
        ));
        // On Customize pages, hovering toggles/sliders below the preview canvas stays throttled
        assert!(!is_mouse_over_interactive_preview_pos(
            StudioTab::DesktopWidgets,
            TaskbarPage::Folders,
            WidgetPage::CustomizeDateTime,
            Some((240.0, 460.0)),
        ));
        assert!(is_mouse_over_interactive_preview_pos(
            StudioTab::DesktopWidgets,
            TaskbarPage::Folders,
            WidgetPage::CustomizeDateTime,
            Some((240.0, 210.0)),
        ));
        // Non-animated tabs (Wallpaper / Suite Gallery / Settings) never request 30 FPS
        assert!(!is_mouse_over_interactive_preview_pos(
            StudioTab::Wallpaper,
            TaskbarPage::Folders,
            WidgetPage::Gallery,
            Some((300.0, 250.0)),
        ));
    }

    #[test]
    fn multi_select_app_launcher_picker_batch_capacity_search_and_replace() {
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }

        let mut cfg = AppConfig::default();
        cfg.apps = vec![
            AppShortcut {
                name: "7-Zip".to_string(),
                path: r"shell:AppsFolder\7Zip".to_string(),
                offset_x: 12,
                offset_y: -8,
            },
            AppShortcut {
                name: "AntiPilot".to_string(),
                path: r"shell:AppsFolder\AntiPilot".to_string(),
                offset_x: 24,
                offset_y: 16,
            },
        ];

        let mut sc = SettingsController::new(HINSTANCE::default());
        sc.draft_cfg = cfg.clone();
        sc.draft_initialized = true;
        sc.active_tab = StudioTab::DesktopWidgets;
        sc.widget_page = WidgetPage::CustomizeApps;

        let mock_installed: Vec<InstalledAppInfo> = (0..14)
            .map(|i| {
                if i == 0 {
                    InstalledAppInfo {
                        name: "7-Zip".to_string(),
                        path: r"shell:appsfolder\7zip".to_string(), // case-insensitive dup of slot 0
                    }
                } else {
                    InstalledAppInfo {
                        name: format!("MockApp {:02}", i),
                        path: format!(r"shell:AppsFolder\MockApp{:02}", i),
                    }
                }
            })
            .collect();

        // 1. Clicking "+ Add App" opens multi-select mode
        let cmd = sc.activate_zone(HitZone::AddAppSlot, &mut cfg);
        assert!(matches!(cmd, SettingsCommand::None));
        assert_eq!(sc.widget_page, WidgetPage::PickInstalledApp);
        assert_eq!(sc.pick_replace_slot, None);
        assert!(sc.pick_selected_apps.is_empty());

        sc.installed_apps = mock_installed.clone();
        sc.installed_loaded = true;
        sc.installed_scanning = false;

        // Footer Clear & Commit buttons are inactive when 0 apps selected
        assert_eq!(sc.hit_test(375.0, 603.0), HitZone::None);
        assert_eq!(sc.hit_test(640.0, 603.0), HitZone::None);
        assert_eq!(sc.hit_test(478.0, 603.0), HitZone::BtnBackFromPicker);

        // 2. Clicking already-in-dock app (case-insensitive) is ignored and stays on picker
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(0), &mut cfg);
        assert!(sc.pick_selected_apps.is_empty());
        assert_eq!(sc.widget_page, WidgetPage::PickInstalledApp);

        // 3. Selecting multiple apps stays on PickInstalledApp & toggles cleanly
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(1), &mut cfg);
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(3), &mut cfg);
        assert_eq!(sc.widget_page, WidgetPage::PickInstalledApp);
        assert_eq!(sc.pick_selected_apps.len(), 2);

        // Toggle off MockApp 01, then re-select after searching & scrolling
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(1), &mut cfg);
        assert_eq!(sc.pick_selected_apps.len(), 1);
        assert_eq!(sc.pick_selected_apps[0].0, "MockApp 03");

        // Search filter + scroll preserves existing selections
        sc.app_search_query = "MockApp 1".to_string();
        let filtered = filter_installed_indices(&sc.installed_apps, &sc.app_search_query);
        assert!(filtered.contains(&11) && filtered.contains(&12));
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(11), &mut cfg);
        sc.app_search_query.clear();
        sc.installed_scroll = 1;
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(12), &mut cfg);
        assert_eq!(sc.pick_selected_apps.len(), 3);
        assert_eq!(
            sc.pick_selected_apps.iter().map(|(n, _)| n.as_str()).collect::<Vec<_>>(),
            vec!["MockApp 03", "MockApp 11", "MockApp 12"]
        );

        // Footer Clear & Add Selected (3) hit-tests are active when selections exist
        assert_eq!(sc.hit_test(375.0, 603.0), HitZone::BtnClearSelectedApps);
        assert_eq!(sc.hit_test(640.0, 603.0), HitZone::BtnCommitSelectedApps);

        // Render smoke-test in multi-select mode
        sc.ensure_graphics_init();
        let _ = sc.backbuf.ensure_size(760, 640);
        sc.u = 1.0;
        assert!(sc.render_d2d(&cfg), "PickInstalledApp multi-select must render cleanly");

        // 4. Capacity clamping at 12 total apps (2 already in dock => max 10 selectable)
        for idx in 1..=13 {
            let _ = sc.activate_zone(HitZone::PickInstalledAppCard(idx), &mut cfg);
        }
        // Clear & fill up to exact capacity (10 remaining slots)
        let _ = sc.activate_zone(HitZone::BtnClearSelectedApps, &mut cfg);
        assert!(sc.pick_selected_apps.is_empty());
        for idx in 1..=13 {
            let _ = sc.activate_zone(HitZone::PickInstalledAppCard(idx), &mut cfg);
        }
        assert_eq!(
            sc.pick_selected_apps.len(),
            10,
            "Selection must clamp to remaining capacity (12 - 2 = 10)"
        );

        // Deselect 1, verify we can pick MockApp 13 instead
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(1), &mut cfg);
        assert_eq!(sc.pick_selected_apps.len(), 9);
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(13), &mut cfg);
        assert_eq!(sc.pick_selected_apps.len(), 10);

        // 5. Commit batch via Add Selected (N) -> applies to both draft_cfg and live cfg
        let _ = sc.activate_zone(HitZone::BtnClearSelectedApps, &mut cfg);
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(2), &mut cfg);
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(5), &mut cfg);
        let _ = sc.activate_zone(HitZone::PickInstalledAppCard(9), &mut cfg);
        let cmd_commit = sc.activate_zone(HitZone::BtnCommitSelectedApps, &mut cfg);
        assert!(
            matches!(cmd_commit, SettingsCommand::WidgetsConfigUpdated),
            "Batch commit must persist & live-apply to App Launchers Dock"
        );
        assert_eq!(sc.widget_page, WidgetPage::CustomizeApps);
        assert!(sc.pick_selected_apps.is_empty());
        assert!(sc.applied_flash);
        assert_eq!(sc.draft_cfg.apps.len(), 5);
        assert_eq!(cfg.apps.len(), 5);
        assert_eq!(cfg.apps[2].name, "MockApp 02");
        assert_eq!(cfg.apps[3].name, "MockApp 05");
        assert_eq!(cfg.apps[4].name, "MockApp 09");

        // 6. Single-slot "Choose..." replace mode preserves slot offsets and closes immediately
        let _ = sc.activate_zone(HitZone::BrowseApp(1), &mut cfg);
        assert_eq!(sc.widget_page, WidgetPage::PickInstalledApp);
        assert_eq!(sc.pick_replace_slot, Some(1));
        sc.installed_apps = mock_installed;
        sc.installed_loaded = true;
        assert!(sc.render_d2d(&cfg), "PickInstalledApp replace mode must render cleanly");

        let cmd_rep = sc.activate_zone(HitZone::PickInstalledAppCard(7), &mut cfg);
        assert!(matches!(cmd_rep, SettingsCommand::WidgetsConfigUpdated));
        assert_eq!(sc.widget_page, WidgetPage::CustomizeApps);
        assert_eq!(cfg.apps.len(), 5);
        assert_eq!(cfg.apps[1].name, "MockApp 07");
        assert_eq!(cfg.apps[1].offset_x, 24);
        assert_eq!(cfg.apps[1].offset_y, 16);

        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

    #[test]
    fn bug5_granular_per_widget_element_toggles_and_all_off_zero_pixels() {
        use windows::Win32::System::Com::{CoInitializeEx, CoUninitialize, COINIT_APARTMENTTHREADED};
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }

        // 1. INI save/load roundtrip & backward-compatible defaults
        let mut cfg = AppConfig::default();
        assert!(cfg.dt_show_clock);
        assert!(cfg.apps_show_tiles);
        assert!(cfg.music_show_title);
        assert!(cfg.cc_show_dividers);
        assert!(cfg.ext_widgets.iter().all(|w| w.show_primary));

        cfg.dt_show_clock = false;
        cfg.apps_show_tiles = false;
        cfg.music_show_title = false;
        cfg.cc_show_dividers = false;
        cfg.ext_widgets[ExtWidgetId::Weather.idx()].show_primary = false;
        let tmp_ini = std::env::temp_dir().join("autumn_bug5_roundtrip.autumn");
        crate::config::export_setup_to_path(&cfg, &tmp_ini).expect("export setup");
        let parsed = crate::config::import_setup_from_path(&tmp_ini, &AppConfig::default()).expect("import setup");
        let _ = std::fs::remove_file(&tmp_ini);
        assert!(!parsed.dt_show_clock);
        assert!(!parsed.apps_show_tiles);
        assert!(!parsed.music_show_title);
        assert!(!parsed.cc_show_dividers);
        assert!(!parsed.ext_widgets[ExtWidgetId::Weather.idx()].show_primary);
        assert!(
            parsed.ext_widgets[ExtWidgetId::SearchBar.idx()].show_primary,
            "Per-widget isolation: Weather show_primary=false must not affect SearchBar"
        );

        // 2. Direct2D rendering into a clear 520x380 DibBuffer:
        //    When all element toggles for a widget are OFF, 0 pixels must be drawn (even with Hover FX active!)
        let mut sc = SettingsController::new(HINSTANCE::default());
        sc.ensure_graphics_init();
        let mut buf = DibBuffer::new();
        assert!(buf.ensure_size(520, 380));
        let rc = RECT { left: 0, top: 0, right: 520, bottom: 380 };
        let d2d = sc.d2d_factory.as_ref().unwrap().clone();
        let dw = sc.dwrite_factory.as_ref().unwrap().clone();
        let dc_rt = sc.dc_rt.as_ref().unwrap().clone();
        unsafe {
            let _ = dc_rt.BindDC(buf.mem_dc, &rc);
        }

        let count_drawn_pixels = |buf: &DibBuffer| -> usize {
            let total = (buf.width * buf.height * 4) as usize;
            let slice = unsafe { std::slice::from_raw_parts(buf.bits, total) };
            slice.chunks_exact(4).filter(|px| px[0] != 0 || px[1] != 0 || px[2] != 0 || px[3] != 0).count()
        };
        let clear_buf = |rt: &ID2D1DCRenderTarget| unsafe {
            rt.BeginDraw();
            rt.Clear(Some(&D2D1_COLOR_F { r: 0.0, g: 0.0, b: 0.0, a: 0.0 }));
            let _ = rt.EndDraw(None, None);
        };

        let mut active_sim = VizSnapshot::default();
        active_sim.hover_mix = 1.0;

        // 2a. Clock (FlipMech & Signature & ChronoDial): All OFF = 0 pixels
        for &style in &[ClockStyle::FlipMech, ClockStyle::Signature, ClockStyle::ChronoDial] {
            let mut c = AppConfig::default();
            c.dt_style = style;
            c.dt_hover_fx = TaskbarVizStyle::HoverSakura;
            c.dt_show_plate = false;
            c.dt_show_clock = false;
            c.dt_show_spine = false;
            c.dt_show_orb = false;
            c.dt_show_seconds = false;
            c.dt_show_weekday = false;
            c.dt_show_date = false;
            c.dt_show_ampm = false;
            assert!(c.is_datetime_all_elements_off());

            clear_buf(&dc_rt);
            unsafe {
                dc_rt.BeginDraw();
                draw_datetime_widget_full(
                    &dc_rt,
                    &dw,
                    None,
                    20.0,
                    20.0,
                    1.0,
                    &c,
                    true,
                    None,
                    Some(&active_sim),
                );
                let _ = dc_rt.EndDraw(None, None);
            }
            assert_eq!(
                count_drawn_pixels(&buf),
                0,
                "ClockStyle::{:?} with all element toggles OFF must render 0 pixels",
                style
            );
        }

        // 2b. App Launchers Dock: All OFF = 0 pixels
        {
            let mut c = AppConfig::default();
            c.apps_hover_fx = TaskbarVizStyle::HoverFire;
            c.apps_show_plate = false;
            c.apps_show_tiles = false;
            c.apps_show_labels = false;
            c.apps_show_dots = false;
            c.apps_show_add_tile = false;
            assert!(c.is_apps_all_elements_off());
            let tiles = [AppTileDrawItem {
                label: "Terminal",
                bmp: None,
                rel_x: 0.0,
                rel_y: 0.0,
                hovered: true,
                is_add_tile: false,
            }];
            clear_buf(&dc_rt);
            unsafe {
                dc_rt.BeginDraw();
                draw_apps_widget_with_boxes(&dc_rt, &dw, None, 20.0, 20.0, 1.0, &c, &tiles, Some(&active_sim), None);
                let _ = dc_rt.EndDraw(None, None);
            }
            assert_eq!(count_drawn_pixels(&buf), 0, "Apps Dock with all element toggles OFF must render 0 pixels");
        }

        // 2c. System Vitals (Styles 0..=4): All OFF = 0 pixels
        for st in 0..=4u8 {
            let mut c = AppConfig::default();
            c.vitals_style = st;
            c.vitals_hover_fx = TaskbarVizStyle::HoverWater;
            c.vitals_show_plate = false;
            c.vitals_show_cpu = false;
            c.vitals_show_ram = false;
            c.vitals_show_power = false;
            c.vitals_show_buttons = false;
            c.vitals_show_bars = false;
            c.vitals_show_dividers = false;
            assert!(c.is_vitals_all_elements_off());
            clear_buf(&dc_rt);
            unsafe {
                dc_rt.BeginDraw();
                draw_vitals_widget_with_telemetry_and_viz(
                    &dc_rt,
                    &dw,
                    Some(&d2d),
                    None,
                    20.0,
                    20.0,
                    1.0,
                    &c,
                    42.0,
                    35.0,
                    68.0,
                    54.0,
                    88.0,
                    WidgetHitZone::None,
                    Some(&active_sim),
                );
                let _ = dc_rt.EndDraw(None, None);
            }
            assert_eq!(count_drawn_pixels(&buf), 0, "Vitals style {} with all element toggles OFF must render 0 pixels", st);
        }

        // 2d. Music Player (DynamicIslandCapsule, VinylDeck, CassetteDeck): All OFF = 0 pixels
        for &mst in &[MusicStyle::DynamicIslandCapsule, MusicStyle::VinylDeck, MusicStyle::CassetteDeck] {
            let mut c = AppConfig::default();
            c.music_style = mst;
            c.music_hover_fx = TaskbarVizStyle::HoverCosmic;
            c.music_show_plate = false;
            c.music_show_cover = false;
            c.music_show_title = false;
            c.music_show_artist = false;
            c.music_show_controls = false;
            c.music_show_viz = false;
            c.music_show_badge = false;
            assert!(c.is_music_all_elements_off());
            let media = MediaSnapshot::default();
            let bands = [0.5f32; 12];
            clear_buf(&dc_rt);
            unsafe {
                dc_rt.BeginDraw();
                draw_music_widget_with_viz(
                    &dc_rt,
                    &dw,
                    Some(&d2d),
                    None,
                    20.0,
                    20.0,
                    1.0,
                    &c,
                    &media,
                    &bands,
                    None,
                    WidgetHitZone::None,
                    Some(&active_sim),
                );
                let _ = dc_rt.EndDraw(None, None);
            }
            assert_eq!(count_drawn_pixels(&buf), 0, "MusicStyle::{:?} with all element toggles OFF must render 0 pixels", mst);
        }

        // 2e. Quick Control Center: All OFF = 0 pixels
        {
            let mut c = AppConfig::default();
            c.cc_hover_fx = TaskbarVizStyle::HoverSnow;
            c.cc_show_plate = false;
            c.cc_show_tiles = false;
            c.cc_show_labels = false;
            c.cc_show_bright = false;
            c.cc_show_vol = false;
            c.cc_show_scrollbar = false;
            c.cc_show_dividers = false;
            assert!(c.is_cc_all_elements_off());
            let cc_snap = CcSnapshot::default();
            clear_buf(&dc_rt);
            unsafe {
                dc_rt.BeginDraw();
                draw_control_center_widget_live_with_viz(
                    &dc_rt,
                    &dw,
                    Some(&d2d),
                    None,
                    20.0,
                    20.0,
                    1.0,
                    &c,
                    &cc_snap,
                    0.0,
                    WidgetHitZone::None,
                    None,
                    None,
                    Some(&active_sim),
                );
                let _ = dc_rt.EndDraw(None, None);
            }
            assert_eq!(count_drawn_pixels(&buf), 0, "Control Center with all element toggles OFF must render 0 pixels");
        }

        // 2f. All 14 Extended Widgets: All OFF = 0 pixels
        let cc_snap = CcSnapshot::default();
        for &id in &ExtWidgetId::ALL {
            let mut c = AppConfig::default();
            let ew = &mut c.ext_widgets[id.idx()];
            ew.hover_fx = TaskbarVizStyle::HoverSakura;
            ew.show_plate = false;
            ew.show_header = false;
            ew.show_primary = false;
            ew.show_icon = false;
            ew.show_dividers = false;
            ew.show_footer = false;
            assert!(ew.is_all_elements_off());
            clear_buf(&dc_rt);
            unsafe {
                dc_rt.BeginDraw();
                draw_ext_widget_with_viz(
                    &dc_rt,
                    &dw,
                    Some(&d2d),
                    None,
                    20.0,
                    20.0,
                    1.0,
                    id,
                    &c,
                    &sc.preview_ext_state,
                    &cc_snap,
                    WidgetHitZone::None,
                    Some(&active_sim),
                );
                let _ = dc_rt.EndDraw(None, None);
            }
            assert_eq!(
                count_drawn_pixels(&buf),
                0,
                "ExtWidgetId::{:?} with all element toggles OFF must render 0 pixels",
                id
            );
        }

        buf.release();
        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

    #[test]
    fn music_themes_gallery_and_viz_color_customizer_d2d_verify() {
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }
        let mut sc = SettingsController::new(HINSTANCE::default());
        sc.win_w = 760;
        sc.win_h = 640;
        sc.u = 1.0;
        sc.ensure_graphics_init();
        assert!(sc.backbuf.ensure_size(760, 640));

        let mut cfg = AppConfig::default();
        cfg.apply_taskbar_theme_preset(TaskbarTheme::VuPeakStudio);
        sc.draft_cfg = cfg.clone();
        sc.active_tab = StudioTab::Taskbar;
        sc.tb_folder = TaskbarThemeFolder::MusicThemes;
        sc.taskbar_page = TaskbarPage::Themes;
        assert!(
            sc.render_d2d(&cfg),
            "Music Themes gallery with 6 curated palettes must render cleanly in Direct2D"
        );

        // Customize page exposes Mode pills, 8 color swatches, and continuous Hue slider
        sc.taskbar_page = TaskbarPage::Customize;
        assert_eq!(
            sc.hit_test(140.0, 368.0),
            HitZone::SetTbVizColorMode(VizColorMode::ThemeNative)
        );
        assert_eq!(
            sc.hit_test(210.0, 368.0),
            HitZone::SetTbVizColorMode(VizColorMode::CustomAccent)
        );
        assert_eq!(
            sc.hit_test(286.0, 368.0),
            HitZone::SetTbVizColorMode(VizColorMode::MatchWallpaper)
        );
        assert_eq!(sc.hit_test(346.0, 368.0), HitZone::SetTbVizSwatch(0));
        assert_eq!(sc.hit_test(376.0, 368.0), HitZone::SetTbVizSwatch(1));
        assert_eq!(sc.hit_test(300.0, 396.0), HitZone::Slider(SliderKind::TbVizHue));

        // Clicking swatch #1 (Synth Magenta) switches to CustomAccent and sets exact RGB
        let cmd_sw = sc.activate_zone(HitZone::SetTbVizSwatch(1), &mut cfg);
        assert!(matches!(cmd_sw, SettingsCommand::StyleUpdated));
        assert_eq!(cfg.tb_viz_color_mode, VizColorMode::CustomAccent);
        assert_eq!(cfg.tb_viz_accent_rgb, VizColorMode::SWATCHES[1].0);
        assert!(!cfg.tb_match_wallpaper);
        assert!(sc.render_d2d(&cfg), "Customize page with custom visualizer swatch must render cleanly");

        // Dragging Hue slider updates accent RGB live
        let cmd_hue = sc.update_slider_from_x(SliderKind::TbVizHue, 391.0, &mut cfg);
        assert!(matches!(cmd_hue, Some(SettingsCommand::StylePreview)));
        assert_eq!(cfg.tb_viz_color_mode, VizColorMode::CustomAccent);
        assert_ne!(cfg.tb_viz_accent_rgb, VizColorMode::SWATCHES[1].0);

        // Switching to MatchWallpaper keeps tb_match_wallpaper synced
        let cmd_wp = sc.activate_zone(
            HitZone::SetTbVizColorMode(VizColorMode::MatchWallpaper),
            &mut cfg,
        );
        assert!(matches!(cmd_wp, SettingsCommand::StyleUpdated));
        assert!(cfg.tb_match_wallpaper);

        // Returning to ThemeNative restores VuPeakStudio's Tri-Color LED mode
        let _ = sc.activate_zone(
            HitZone::SetTbVizColorMode(VizColorMode::ThemeNative),
            &mut cfg,
        );
        assert!(!cfg.tb_match_wallpaper);
        assert!(crate::taskbar_styler::is_vu_tricolor_active(&cfg));
        assert!(sc.render_d2d(&cfg), "Customize page with VuPeakStudio Tri-Color LED must render cleanly");

        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

    #[test]
    fn bug7_taskbar_and_dock_per_element_toggles_and_all_off_zero_pixels() {
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }
        let mut sc = SettingsController::new(HINSTANCE::default());
        sc.win_w = 760;
        sc.win_h = 640;
        sc.u = 1.0;
        sc.ensure_graphics_init();
        assert!(sc.backbuf.ensure_size(760, 640));

        // 1. Verify Dock customization UI element toggles across theme-specific visible tabs
        let mut cfg = AppConfig::default();
        cfg.apply_taskbar_theme_preset(TaskbarTheme::RealisticWaterDock);
        sc.draft_cfg = cfg.clone();
        sc.active_tab = StudioTab::Taskbar;
        sc.taskbar_page = TaskbarPage::Customize;
        sc.dock_custom_tab = DockCustomTab::Modules;

        // RealisticWaterDock (FishEyeShelf, Bar OFF) exposes ShelfFrame, AppDock, Clock, SystemTray, Utilities (NO HudWing!)
        let water_tabs = visible_dock_module_tabs(&cfg);
        assert!(!water_tabs.contains(&TaskbarWidgetTab::HudWing));
        for &tab in &water_tabs {
            sc.tb_widget_tab = tab;
            assert!(
                sc.render_d2d(&cfg),
                "Dock Customize tab {:?} must render cleanly with per-element pills",
                tab
            );
            let elems = dock_widget_elem_toggles(tab, &sc.draft_cfg);
            let total = elems.len();
            assert!(total >= 2, "Tab {:?} must expose at least 2 element toggles", tab);
            for (idx, &(_, initial_on, k)) in elems.iter().enumerate() {
                assert!(initial_on, "Element {} on tab {:?} must default to ON", k, tab);
                let (x0, y0, x1, y1) = dock_widget_elem_pill_rect(idx, total);
                let cx = (x0 + x1) * 0.5;
                let cy = (y0 + y1) * 0.5;
                assert_eq!(
                    sc.hit_test(cx, cy),
                    HitZone::TbWidgetElemToggle(k),
                    "Hit-test failed for element pill {} on tab {:?}",
                    k,
                    tab
                );
                let cmd = sc.activate_zone(HitZone::TbWidgetElemToggle(k), &mut cfg);
                assert!(matches!(cmd, SettingsCommand::MacDockUpdated));
            }
            let elems_after = dock_widget_elem_toggles(tab, &sc.draft_cfg);
            for &(_, now_on, k) in &elems_after {
                assert!(!now_on, "Element {} on tab {:?} must be OFF after toggle", k, tab);
            }
        }
        // Toggle remaining non-rendered hidden flags so full all-off check passes cleanly
        cfg.w_hud.show_telemetry = false;
        cfg.w_hud.show_active_app = false;
        cfg.w_util.show_search = false;
        cfg.w_util.show_taskview = false;
        assert!(cfg.w_shelf.is_all_elements_off());
        assert!(cfg.w_apps.is_all_elements_off());
        assert!(cfg.w_clock.is_all_elements_off());
        assert!(cfg.w_tray.is_all_elements_off());
        assert!(cfg.w_hud.is_all_elements_off());
        assert!(cfg.w_util.is_all_elements_off());
        assert!(cfg.is_dock_all_elements_off());
        assert!(!crate::dock_themes::is_ambient_animated_cfg(&cfg));

        // Verify Clean & Minimal OS26 Liquid Glass Light theme-specific Modules filtering:
        // - Bar ON hides Clock, SystemTray, and HudWing; Utilities exposes only Start, Trash, Studio!
        let mut os26 = AppConfig::default();
        os26.apply_taskbar_theme_preset(TaskbarTheme::Os26LiquidGlassLight);
        let os26_bar_on_tabs = visible_dock_module_tabs(&os26);
        assert_eq!(
            os26_bar_on_tabs,
            vec![
                TaskbarWidgetTab::ShelfFrame,
                TaskbarWidgetTab::AppDock,
                TaskbarWidgetTab::Utilities,
            ]
        );
        let os26_util_elems = dock_widget_elem_toggles(TaskbarWidgetTab::Utilities, &os26);
        assert_eq!(os26_util_elems.len(), 3, "OS26 Utilities must only show Start, Trash, Studio");
        os26.dock_bar_enabled = false;
        let os26_bar_off_tabs = visible_dock_module_tabs(&os26);
        assert!(os26_bar_off_tabs.contains(&TaskbarWidgetTab::Clock));
        assert!(os26_bar_off_tabs.contains(&TaskbarWidgetTab::SystemTray));
        assert!(!os26_bar_off_tabs.contains(&TaskbarWidgetTab::HudWing));

        // Verify CyberpunkHudDock (HudConsoleDeck) DOES expose HudWing & Edge Sliver
        let mut cyber = AppConfig::default();
        cyber.apply_taskbar_theme_preset(TaskbarTheme::CyberpunkHudDock);
        assert!(visible_dock_module_tabs(&cyber).contains(&TaskbarWidgetTab::HudWing));
        // Verify barless IndependentOrbs hides ShelfFrame
        let mut orbs = AppConfig::default();
        orbs.apply_taskbar_theme_preset(TaskbarTheme::BubblesDark);
        assert!(!visible_dock_module_tabs(&orbs).contains(&TaskbarWidgetTab::ShelfFrame));

        // 2. Verify Native Taskbar Customize UI element toggles (Backdrop, Border Rim, Live FX)
        let mut native_cfg = AppConfig::default();
        native_cfg.apply_taskbar_theme_preset(TaskbarTheme::LiveMusicBars);
        sc.draft_cfg = native_cfg.clone();
        assert!(sc.render_d2d(&native_cfg));
        for idx in 0..3usize {
            let (x0, y0, x1, y1) = native_tb_elem_pill_rect(idx);
            let cx = (x0 + x1) * 0.5;
            let cy = (y0 + y1) * 0.5;
            assert_eq!(
                sc.hit_test(cx, cy),
                HitZone::ToggleNativeTbElem(idx as u8)
            );
            let cmd = sc.activate_zone(HitZone::ToggleNativeTbElem(idx as u8), &mut native_cfg);
            assert!(matches!(cmd, SettingsCommand::StyleUpdated));
        }
        assert!(!native_cfg.tb_show_backdrop);
        assert!(!native_cfg.tb_show_rim);
        assert!(!native_cfg.tb_show_fx);
        assert!(native_cfg.is_native_tb_all_elements_off());

        // 3. Verify INI persistence round-trip for all new Dock & Native Taskbar flags
        cfg.tb_show_backdrop = false;
        cfg.tb_show_rim = false;
        cfg.tb_show_fx = false;
        let tmp_ini = std::env::temp_dir().join("autumn_bug7_roundtrip.autumn");
        crate::config::export_setup_to_path(&cfg, &tmp_ini).expect("export setup");
        let parsed = crate::config::import_setup_from_path(&tmp_ini, &AppConfig::default()).expect("import setup");
        let _ = std::fs::remove_file(&tmp_ini);
        assert!(!parsed.tb_show_backdrop);
        assert!(!parsed.tb_show_rim);
        assert!(!parsed.tb_show_fx);
        assert!(parsed.is_native_tb_all_elements_off());
        assert!(parsed.w_shelf.is_all_elements_off());
        assert!(parsed.w_apps.is_all_elements_off());
        assert!(parsed.w_clock.is_all_elements_off());
        assert!(parsed.w_tray.is_all_elements_off());
        assert!(parsed.w_hud.is_all_elements_off());
        assert!(parsed.w_util.is_all_elements_off());
        assert!(parsed.is_dock_all_elements_off());

        // 4. Direct2D pixel verification: "All OFF = Show Nothing" (0 pixels rendered)
        let mut buf = DibBuffer::new();
        assert!(buf.ensure_size(500, 120));
        let d2d = sc.d2d_factory.as_ref().unwrap().clone();
        let dc_rt = sc.dc_rt.as_ref().unwrap().clone();
        let rc = RECT {
            left: 0,
            top: 0,
            right: 500,
            bottom: 120,
        };
        unsafe {
            let _ = dc_rt.BindDC(buf.mem_dc, &rc);
        }
        let brush = unsafe {
            dc_rt
                .CreateSolidColorBrush(&D2D1_COLOR_F {
                    r: 1.0,
                    g: 1.0,
                    b: 1.0,
                    a: 1.0,
                }, None)
                .unwrap()
        };

        let clear_buf = |rt: &ID2D1DCRenderTarget| unsafe {
            rt.BeginDraw();
            rt.Clear(Some(&D2D1_COLOR_F {
                r: 0.0,
                g: 0.0,
                b: 0.0,
                a: 0.0,
            }));
            let _ = rt.EndDraw(None, None);
        };
        let count_drawn_pixels = |b: &DibBuffer| -> usize {
            let total = (b.width * b.height * 4) as usize;
            let slice = unsafe { std::slice::from_raw_parts(b.bits, total) };
            slice
                .chunks_exact(4)
                .filter(|px| px[0] != 0 || px[1] != 0 || px[2] != 0 || px[3] != 0)
                .count()
        };

        let shelf_r = D2D_RECT_F {
            left: 20.0,
            top: 20.0,
            right: 460.0,
            bottom: 90.0,
        };
        let slot_r = D2D_RECT_F {
            left: 138.0,
            top: 33.0,
            right: 182.0,
            bottom: 77.0,
        };
        let pal = crate::theme::ThemePalette::autumn();
        let tf_body = sc.res.as_ref().map(|r| &r.tf_title);
        clear_buf(&dc_rt);
        unsafe {
            dc_rt.BeginDraw();
            crate::dock_themes::draw_dock_shelf_and_art_with_ripple(
                &dc_rt,
                Some(&d2d),
                &brush,
                shelf_r,
                &cfg,
                &pal,
                0.0,
                1.0,
                0.5,
                false,
                1.0,
                false,
                None,
            );
            crate::dock_themes::draw_dock_divider_styled(
                &dc_rt,
                &brush,
                120.0,
                55.0,
                shelf_r,
                &cfg,
                false,
                1.0,
            );
            crate::dock_themes::draw_dock_slot_fx_styled(
                &dc_rt,
                Some(&d2d),
                &brush,
                slot_r,
                160.0,
                55.0,
                44.0,
                shelf_r,
                &cfg,
                crate::dock_themes::TaskbarWidgetId::AppDock,
                None,
                true,
                true,
                true,
                false,
                false,
                0.0,
                0,
                1.0,
            );
            crate::dock_themes::draw_dock_indicator_styled(
                &dc_rt,
                &brush,
                &cfg,
                None,
                0,
                160.0,
                84.0,
                slot_r,
                shelf_r,
                crate::config::MacDockEdge::Bottom,
                2,
                true,
                1.0,
            );
            crate::dock_themes::draw_dock_clock_module(
                &dc_rt,
                &brush,
                tf_body,
                D2D_RECT_F {
                    left: 320.0,
                    top: 30.0,
                    right: 400.0,
                    bottom: 80.0,
                },
                &cfg,
                &pal,
                "14:30",
                "Mon 23 Nov",
                14,
                30,
                0,
                0.0,
                false,
                1.0,
            );
            let _ = dc_rt.EndDraw(None, None);
        }
        assert_eq!(
            count_drawn_pixels(&buf),
            0,
            "Dock shelf, divider, slot FX, indicator, and clock module with all element toggles OFF must draw 0 pixels"
        );

        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

    #[test]
    fn suite_gallery_dock_syncs_taskbar_studio_folder_page_and_clears_overrides_on_switch() {
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }
        let mut sc = SettingsController::new(HINSTANCE::default());
        sc.win_w = 760;
        sc.win_h = 640;
        sc.u = 1.0;
        sc.ensure_graphics_init();
        assert!(sc.backbuf.ensure_size(760, 640));

        assert_eq!(
            TaskbarThemeFolder::InteractiveDocks.label(),
            "Interactive Docks (20)"
        );
        assert_eq!(
            TaskbarThemeFolder::CleanMinimal.label(),
            "Clean & Minimal (20)"
        );
        assert_eq!(TaskbarThemeFolder::All.label(), "All Themes (90)");

        // 1. Apply a Suite with Deep-Space Telemetry (StarfieldWarpDock, Page 4/4 of Interactive Docks)
        let suite_idx = crate::suites::SUITES
            .iter()
            .position(|s| s.id == "cosmic_eclipse")
            .expect("cosmic_eclipse suite");
        let mut cfg = AppConfig::default();
        let cmd = sc.activate_zone(HitZone::ApplySuite(suite_idx), &mut cfg);
        assert!(matches!(cmd, SettingsCommand::SuiteApplied));
        assert_eq!(cfg.tb_theme, TaskbarTheme::StarfieldWarpDock);
        assert!(cfg.w_apps.custom_glow_rgb.is_some());
        assert_eq!(sc.tb_folder, TaskbarThemeFolder::InteractiveDocks);
        assert_eq!(sc.tb_theme_page, 3, "StarfieldWarpDock is on page 4/4 (index 3)");

        // 2. Switching to Taskbar Studio Folders and opening Interactive Docks auto-jumps to Page 4/4
        let _ = sc.activate_zone(HitZone::TabTaskbar, &mut cfg);
        assert_eq!(sc.taskbar_page, TaskbarPage::Folders);
        assert!(sc.render_d2d(&cfg), "Taskbar Folders must render active Suite dock preview cleanly");

        let _ = sc.activate_zone(
            HitZone::OpenTaskbarFolder(TaskbarThemeFolder::InteractiveDocks),
            &mut cfg,
        );
        assert_eq!(sc.taskbar_page, TaskbarPage::Themes);
        assert_eq!(
            sc.tb_theme_page, 3,
            "Opening Interactive Docks must auto-jump to the page showing active Deep-Space Telemetry"
        );
        assert!(sc.render_d2d(&cfg));

        // 3. Selecting a DIFFERENT Dock theme resets old Suite overrides and updates cleanly
        let cmd2 = sc.activate_zone(
            HitZone::SelectTaskbarTheme(TaskbarTheme::CyberpunkHudDock),
            &mut cfg,
        );
        assert!(matches!(cmd2, SettingsCommand::StyleUpdated));
        assert_eq!(cfg.tb_theme, TaskbarTheme::CyberpunkHudDock);
        assert_eq!(sc.draft_cfg.tb_theme, TaskbarTheme::CyberpunkHudDock);
        assert_eq!(cfg.w_apps.custom_glow_rgb, None);
        assert_eq!(cfg.w_clock.custom_accent_rgb, None);
        assert_eq!(cfg.w_tray.custom_accent_rgb, None);
        assert_eq!(cfg.w_apps.card_style, DockSlotCardStyle::InheritTheme);
        assert_eq!(cfg.w_clock.engine, DockClockEngine::InheritTheme);
        assert_eq!(sc.tb_theme_page, 0);

        // 4. Clicking the ALREADY-active Dock theme opens Customize without wiping user tweaks
        cfg.w_clock.show_seconds = true;
        let _ = sc.activate_zone(
            HitZone::SelectTaskbarTheme(TaskbarTheme::CyberpunkHudDock),
            &mut cfg,
        );
        assert_eq!(sc.taskbar_page, TaskbarPage::Customize);
        assert!(cfg.w_clock.show_seconds);

        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

    #[test]
    fn world_clock_city_picker_and_drives_processes_folder_previews_render_cleanly() {
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }
        let mut sc = SettingsController::new(HINSTANCE::default());
        sc.ensure_graphics_init();
        assert!(sc.backbuf.ensure_size(1140, 972));

        // 1. Studio preview_ext_state must already have realistic Drives & Processes mock telemetry
        assert!(sc.preview_ext_state.drives.len() >= 2);
        assert!(sc.preview_ext_state.top_procs.len() >= 3);

        let mut cfg = AppConfig::default();
        sc.draft_cfg = cfg.clone();
        sc.active_tab = StudioTab::DesktopWidgets;

        // 2. Render Disk Drives Folders (disabled vs enabled) & Process Killer Folders cleanly
        sc.draft_cfg.ext_widgets[ExtWidgetId::Drives.idx()].enabled = false;
        sc.widget_page = WidgetPage::ExtFolders(ExtWidgetId::Drives);
        assert!(sc.render_d2d(&cfg), "Disk Drives Folders (disabled) must render cleanly");

        sc.draft_cfg.ext_widgets[ExtWidgetId::Processes.idx()].enabled = true;
        sc.widget_page = WidgetPage::ExtFolders(ExtWidgetId::Processes);
        assert!(sc.render_d2d(&cfg), "Process Killer Folders (enabled) must render cleanly");

        // 3. World Clock 4th sub-tab ("4. Choose Cities") hit-test, pagination, slot selection, and live update
        sc.widget_page = WidgetPage::CustomizeExt(ExtWidgetId::WorldClock);
        assert_eq!(sc.hit_test(640.0, 318.0), HitZone::ExtSubTabBtn(ExtSubTab::WorldClockCities));
        sc.activate_zone(HitZone::ExtSubTabBtn(ExtSubTab::WorldClockCities), &mut cfg);
        assert_eq!(sc.ext_sub_tab, ExtSubTab::WorldClockCities);
        assert!(sc.render_d2d(&cfg), "World Clock Choose Cities sub-tab must render cleanly");

        // Select Slot 4 -> auto-enables Show 4 Cities (feats[5])
        assert_eq!(sc.hit_test(630.0, 366.0), HitZone::WcSelectSlot(3));
        sc.activate_zone(HitZone::WcSelectSlot(3), &mut cfg);
        assert_eq!(sc.wc_selected_slot, 3);
        assert!(sc.draft_cfg.ext_widgets[ExtWidgetId::WorldClock.idx()].feats[5]);

        // Page to Asia & Pacific (page 3) and pick Bengaluru (index 37 -> col 1, row 0 on page 3)
        sc.wc_city_page = 3;
        assert!(sc.render_d2d(&cfg));
        assert_eq!(sc.hit_test(290.0, 442.0), HitZone::WcPickCity(37));
        let cmd = sc.activate_zone(HitZone::WcPickCity(37), &mut cfg);
        assert!(matches!(cmd, SettingsCommand::WidgetsConfigUpdated));
        assert_eq!(sc.draft_cfg.world_clock_cities[3], "Bengaluru");
        assert_eq!(cfg.world_clock_cities[3], "Bengaluru");

        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

    #[test]
    fn dock_sliders_emit_preview_during_drag_and_commit_on_release() {
        let mut sc = SettingsController::new(HINSTANCE::default());
        let mut cfg = AppConfig::default();
        cfg.apply_taskbar_theme_preset(TaskbarTheme::RealisticWaterDock);
        sc.draft_cfg = cfg.clone();

        // Live drag updates size/magnification via lightweight MacDockPreview (no OS workarea storm)
        let cmd_sz = sc.update_slider_from_x(SliderKind::MacDockIconSize, 520.0, &mut cfg);
        assert!(
            matches!(cmd_sz, Some(SettingsCommand::MacDockPreview)),
            "MacDockIconSize drag must emit lightweight MacDockPreview, not full MacDockUpdated"
        );
        assert_eq!(cfg.mac_dock_icon_size, sc.draft_cfg.mac_dock_icon_size);

        let cmd_mag = sc.update_slider_from_x(SliderKind::MacDockMagPct, 480.0, &mut cfg);
        assert!(
            matches!(cmd_mag, Some(SettingsCommand::MacDockPreview)),
            "MacDockMagPct drag must emit lightweight MacDockPreview, not full MacDockUpdated"
        );
        assert_eq!(cfg.mac_dock_mag_pct, sc.draft_cfg.mac_dock_mag_pct);

        // Rapid WM_MOUSEMOVE within 16ms throttles live preview emissions while still updating values
        let dummy_hwnd = HWND(0x1234usize as *mut c_void);
        sc.hwnd = dummy_hwnd;
        sc.draft_initialized = true;
        sc.tracking_mouse = true;
        sc.dragging_slider = Some(SliderKind::MacDockIconSize);
        sc.last_live_preview_at = Some(Instant::now());
        let lp_move = LPARAM(320isize);
        let move_res = sc.handle_message(dummy_hwnd, WM_MOUSEMOVE, WPARAM(0), lp_move, &mut cfg, false);
        assert!(
            matches!(move_res, Some((_, SettingsCommand::None))),
            "sub-16ms WM_MOUSEMOVE during dock slider drag should throttle preview command"
        );

        // Releasing mouse button commits the final layout & config save via MacDockUpdated
        let up_res = sc.handle_message(dummy_hwnd, WM_LBUTTONUP, WPARAM(0), lp_move, &mut cfg, false);
        assert!(
            matches!(up_res, Some((_, SettingsCommand::MacDockUpdated))),
            "WM_LBUTTONUP on dock slider must commit MacDockUpdated"
        );
        assert!(sc.dragging_slider.is_none());
        sc.hwnd = HWND::default();
    }

    #[test]
    fn clean_minimal_folder_and_all_20_theme_cards_render_cleanly() {
        use windows::Win32::System::Com::{CoInitializeEx, CoUninitialize, COINIT_APARTMENTTHREADED};
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }
        let mut sc = SettingsController::new(HINSTANCE::default());
        sc.win_w = 760;
        sc.win_h = 640;
        sc.u = 1.0;
        sc.ensure_graphics_init();
        assert!(sc.backbuf.ensure_size(760, 640));

        let mut cfg = AppConfig::default();
        cfg.apply_taskbar_theme_preset(TaskbarTheme::Os26LiquidGlassLight);
        sc.draft_cfg = cfg.clone();
        sc.active_tab = StudioTab::Taskbar;
        sc.taskbar_page = TaskbarPage::Folders;

        // Verify all 8 curated folder cards hit-test cleanly in 2+3+3 layout
        assert_eq!(sc.hit_test(180.0, 200.0), HitZone::OpenTaskbarFolder(TaskbarThemeFolder::CleanMinimal));
        assert_eq!(sc.hit_test(560.0, 200.0), HitZone::OpenTaskbarFolder(TaskbarThemeFolder::RealisticMaterials));
        assert_eq!(sc.hit_test(140.0, 340.0), HitZone::OpenTaskbarFolder(TaskbarThemeFolder::InteractiveDocks));
        assert_eq!(sc.hit_test(380.0, 340.0), HitZone::OpenTaskbarFolder(TaskbarThemeFolder::OsDocks));
        assert_eq!(sc.hit_test(620.0, 340.0), HitZone::OpenTaskbarFolder(TaskbarThemeFolder::KineticThemes));
        assert_eq!(sc.hit_test(140.0, 480.0), HitZone::OpenTaskbarFolder(TaskbarThemeFolder::InteractiveElements));
        assert_eq!(sc.hit_test(380.0, 480.0), HitZone::OpenTaskbarFolder(TaskbarThemeFolder::LiveThemes));
        assert_eq!(sc.hit_test(620.0, 480.0), HitZone::OpenTaskbarFolder(TaskbarThemeFolder::MusicThemes));
        assert!(sc.render_d2d(&cfg), "8-folder Taskbar Studio grid must render cleanly");

        let dump_dir = std::env::var("AUTUMN_CLEAN_DUMP_DIR").ok();
        if let Some(ref d) = dump_dir {
            let p = std::path::PathBuf::from(d);
            let _ = std::fs::create_dir_all(&p);
            dump_dib_bmp(&sc.backbuf, &p.join("clean_0_folders.bmp"));
        }

        // Open Clean & Minimal (20) and render all 4 pages (6 + 6 + 6 + 2 = 20 themes)
        sc.activate_zone(HitZone::OpenTaskbarFolder(TaskbarThemeFolder::CleanMinimal), &mut cfg);
        assert_eq!(sc.taskbar_page, TaskbarPage::Themes);
        assert_eq!(sc.tb_folder, TaskbarThemeFolder::CleanMinimal);
        for page in 0..4usize {
            sc.tb_theme_page = page;
            assert!(
                sc.render_d2d(&cfg),
                "Clean & Minimal gallery page {} must render cleanly in Direct2D",
                page + 1
            );
            if let Some(ref d) = dump_dir {
                let p = std::path::PathBuf::from(d);
                dump_dib_bmp(&sc.backbuf, &p.join(format!("clean_p{}.bmp", page + 1)));
            }
        }

        // Select MatterTilesDark from the Clean & Minimal folder and verify animated Virtual Dock switch
        let cmd = sc.activate_zone(
            HitZone::SelectTaskbarTheme(TaskbarTheme::MatterTilesDark),
            &mut cfg,
        );
        assert!(matches!(cmd, SettingsCommand::StyleUpdated));
        assert_eq!(cfg.tb_theme, TaskbarTheme::MatterTilesDark);
        assert!(cfg.mac_dock_enabled);
        assert_eq!(
            crate::dock_themes::dock_spec(cfg.tb_theme).layout,
            crate::config::DockLayoutKind::IndependentOrbs
        );

        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

    fn count_nonzero_dib_pixels(buf: &DibBuffer) -> usize {
        assert!(!buf.bits.is_null() && buf.width > 0 && buf.height > 0);
        let px_count = (buf.width as usize) * (buf.height as usize);
        let slice = unsafe { std::slice::from_raw_parts(buf.bits as *const u32, px_count) };
        slice.iter().filter(|&&px| px != 0).count()
    }

    #[test]
    fn horology_config_ini_roundtrip_and_v208_compat() {
        use crate::config::{parse_config_ini, serialize_config_ini};

        // 1. Every Horology theme variant across Clock (10), Music (10), Ext (10), Vitals (5..=14), CC (4..=13), Apps (4..=13)
        for i in 0..HorologyTheme::COUNT {
            let mut cfg = AppConfig::default();
            cfg.dt_style = ClockStyle::HOROLOGY_FOLDER[i];
            cfg.music_style = MusicStyle::HOROLOGY_FOLDER[i];
            cfg.vitals_style = 5 + (i as u8);
            cfg.cc_tile_style = 4 + (i as u8);
            cfg.apps_tile_shape = 4 + (i as u8);
            for id in ExtWidgetId::ALL {
                cfg.ext_widgets[id.idx()].theme = ExtWidgetTheme::HOROLOGY_FOLDER[i];
            }
            let ini = serialize_config_ini(&cfg);
            let parsed = parse_config_ini(&ini).expect("Horology INI round-trip must parse");
            assert_eq!(parsed.dt_style, ClockStyle::HOROLOGY_FOLDER[i]);
            assert_eq!(parsed.music_style, MusicStyle::HOROLOGY_FOLDER[i]);
            assert_eq!(parsed.vitals_style, 5 + (i as u8));
            assert_eq!(parsed.cc_tile_style, 4 + (i as u8));
            assert_eq!(parsed.apps_tile_shape, 4 + (i as u8));
            for id in ExtWidgetId::ALL {
                assert_eq!(parsed.ext_widgets[id.idx()].theme, ExtWidgetTheme::HOROLOGY_FOLDER[i]);
            }
        }

        // 2. Per-part Horology material customization round-trip across Core + Extended widgets
        let mut cfg = AppConfig::default();
        cfg.dt_horology = HorologyPartConfig {
            bezel_finish: Some(HorologyBezelFinish::RoseGold),
            bezel_rgb: Some(0xD89A72),
            dial_finish: Some(HorologyDialFinish::PorcelainIvory),
            dial_rgb: Some(0xF6F0E4),
            hands_rgb: Some(0x1E4FA8),
            lume_rgb: Some(0x52E5A8),
            glare_pct: 74,
            show_screws: false,
            show_needle_shadows: true,
        };
        cfg.apps_horology = HorologyPartConfig {
            bezel_finish: Some(HorologyBezelFinish::ForgedCarbon),
            bezel_rgb: Some(0x202226),
            dial_finish: Some(HorologyDialFinish::SmokedSkeleton),
            dial_rgb: None,
            hands_rgb: Some(0xFF4F2B),
            lume_rgb: Some(0xFFD24D),
            glare_pct: 25,
            show_screws: true,
            show_needle_shadows: false,
        };
        cfg.vitals_horology.glare_pct = 90;
        cfg.vitals_horology.bezel_finish = Some(HorologyBezelFinish::BeadTitanium);
        cfg.music_horology.dial_finish = Some(HorologyDialFinish::CathedralWalnut);
        cfg.cc_horology.show_screws = false;
        cfg.ext_widgets[ExtWidgetId::Weather.idx()].horology = HorologyPartConfig {
            bezel_finish: Some(HorologyBezelFinish::MatteCeramic),
            bezel_rgb: Some(0x14171D),
            dial_finish: Some(HorologyDialFinish::TapisserieGuilloche),
            dial_rgb: Some(0x102840),
            hands_rgb: Some(0xF0F4FA),
            lume_rgb: Some(0x38D6FF),
            glare_pct: 62,
            show_screws: true,
            show_needle_shadows: true,
        };
        cfg.ext_widgets[ExtWidgetId::RecycleBin.idx()].horology.glare_pct = 12;

        let ini = serialize_config_ini(&cfg);
        let parsed = parse_config_ini(&ini).expect("HorologyPartConfig INI round-trip must parse");
        assert_eq!(parsed.dt_horology, cfg.dt_horology);
        assert_eq!(parsed.apps_horology, cfg.apps_horology);
        assert_eq!(parsed.vitals_horology, cfg.vitals_horology);
        assert_eq!(parsed.music_horology, cfg.music_horology);
        assert_eq!(parsed.cc_horology, cfg.cc_horology);
        assert_eq!(parsed.ext_widgets[ExtWidgetId::Weather.idx()].horology, cfg.ext_widgets[ExtWidgetId::Weather.idx()].horology);
        assert_eq!(parsed.ext_widgets[ExtWidgetId::RecycleBin.idx()].horology, cfg.ext_widgets[ExtWidgetId::RecycleBin.idx()].horology);

        // 3. v2.0.8 INI without any horology keys loads cleanly with defaults
        let legacy_ini = "[AutumnStudioV5]\nwidgets_enabled=1\nvitals_style=4\ncc_tile_style=2\napps_tile_shape=1\ndt_style=glass\n";
        let legacy = parse_config_ini(legacy_ini).expect("Legacy v2.0.8 INI must load cleanly");
        assert_eq!(legacy.vitals_style, 4);
        assert_eq!(legacy.cc_tile_style, 2);
        assert_eq!(legacy.apps_tile_shape, 1);
        assert_eq!(legacy.dt_horology, HorologyPartConfig::default());
        assert_eq!(legacy.ext_widgets[0].horology, HorologyPartConfig::default());
    }

    #[test]
    fn horology_all_19_widgets_x_10_themes_d2d_smoke_and_lru_cache() {
        unsafe {
            let _ = CoInitializeEx(None, COINIT_APARTMENTTHREADED);
        }
        crate::horology_pbr::evict_all();

        let mut sc = SettingsController::new(HINSTANCE::default());
        sc.ensure_graphics_init();
        assert!(sc.backbuf.ensure_size(640, 420));

        let d2d = sc.d2d_factory.as_ref().expect("D2D factory").clone();
        let dw = sc.dwrite_factory.as_ref().expect("DW factory").clone();
        let dc_rt = sc.dc_rt.as_ref().expect("D2D DC RT").clone();
        let rt: windows::Win32::Graphics::Direct2D::ID2D1RenderTarget = dc_rt.clone().into();
        let bind_rc = RECT { left: 0, top: 0, right: 640, bottom: 420 };
        let clear_zero = D2D1_COLOR_F { r: 0.0, g: 0.0, b: 0.0, a: 0.0 };

        let media = MediaSnapshot::default();
        let cc = CcSnapshot::default();
        let ext_state = ExtRuntimeState::new_studio_preview();
        let bands = STUDIO_PREVIEW_BANDS;

        let mut cfg = AppConfig::default();
        cfg.apps = vec![
            AppShortcut { name: "Code".to_string(), path: r"C:\Windows\System32\cmd.exe".to_string(), offset_x: 0, offset_y: 0 },
            AppShortcut { name: "Files".to_string(), path: r"C:\Windows\explorer.exe".to_string(), offset_x: 0, offset_y: 0 },
            AppShortcut { name: "Web".to_string(), path: r"C:\Windows\notepad.exe".to_string(), offset_x: 0, offset_y: 0 },
        ];
        let (offsets, _, _) = apps_layout_offsets(3, 3);
        let app_labels = ["Code", "Files", "Web"];
        let app_tiles: Vec<AppTileDrawItem<'_>> = app_labels.iter().enumerate().map(|(i, &lbl)| AppTileDrawItem {
            label: lbl,
            bmp: None,
            rel_x: offsets[i].0,
            rel_y: offsets[i].1,
            hovered: false,
            is_add_tile: false,
        }).collect();

        // Render all 19 widgets × all 10 Horology themes (190 bespoke renders!)
        for theme_idx in 0..HorologyTheme::COUNT {
            // 1. Clock
            cfg.apply_clock_style_preset(ClockStyle::HOROLOGY_FOLDER[theme_idx]);
            let mut dt_boxes = [ClockElemBox::default(); 8];
            unsafe {
                dc_rt.BindDC(sc.backbuf.mem_dc, &bind_rc).expect("BindDC");
                rt.BeginDraw();
                rt.Clear(Some(&clear_zero));
                draw_datetime_widget_with_boxes(&rt, &dw, None, 40.0, 40.0, 1.0, &cfg, false, Some(&mut dt_boxes));
                rt.EndDraw(None, None).expect("EndDraw Clock");
            }
            assert!(count_nonzero_dib_pixels(&sc.backbuf) > 1000, "Clock Horology #{} must draw pixels", theme_idx);
            assert!(dt_boxes[ClockElemId::Card.idx()].visible, "Clock Horology #{} must record Card box", theme_idx);

            // 2. Music
            cfg.apply_music_style_preset(MusicStyle::HOROLOGY_FOLDER[theme_idx]);
            let mut m_boxes = [ClockElemBox::default(); 6];
            unsafe {
                dc_rt.BindDC(sc.backbuf.mem_dc, &bind_rc).expect("BindDC");
                rt.BeginDraw();
                rt.Clear(Some(&clear_zero));
                draw_music_widget_with_boxes(&rt, &dw, Some(&d2d), None, 40.0, 40.0, 1.0, &cfg, &media, &bands, None, WidgetHitZone::None, None, Some(&mut m_boxes));
                rt.EndDraw(None, None).expect("EndDraw Music");
            }
            assert!(count_nonzero_dib_pixels(&sc.backbuf) > 1000, "Music Horology #{} must draw pixels", theme_idx);
            assert!(m_boxes[5].visible, "Music Horology #{} must record Card box", theme_idx);

            // 3. Vitals
            cfg.vitals_style = 5 + (theme_idx as u8);
            cfg.vitals_show_plate = true;
            let mut v_boxes = [ClockElemBox::default(); 6];
            unsafe {
                dc_rt.BindDC(sc.backbuf.mem_dc, &bind_rc).expect("BindDC");
                rt.BeginDraw();
                rt.Clear(Some(&clear_zero));
                draw_vitals_widget_with_telemetry_and_boxes(&rt, &dw, Some(&d2d), None, 40.0, 40.0, 1.0, &cfg, 28.0, 42.0, 61.0, 56.0, 88.0, WidgetHitZone::None, None, Some(&mut v_boxes));
                rt.EndDraw(None, None).expect("EndDraw Vitals");
            }
            assert!(count_nonzero_dib_pixels(&sc.backbuf) > 1000, "Vitals Horology #{} must draw pixels", theme_idx);
            assert!(v_boxes[5].visible, "Vitals Horology #{} must record Card box", theme_idx);

            // 4. Control Center
            cfg.cc_tile_style = 4 + (theme_idx as u8);
            cfg.cc_show_plate = true;
            let mut cc_boxes = [ClockElemBox::default(); 6];
            unsafe {
                dc_rt.BindDC(sc.backbuf.mem_dc, &bind_rc).expect("BindDC");
                rt.BeginDraw();
                rt.Clear(Some(&clear_zero));
                draw_control_center_widget_with_boxes(&rt, &dw, Some(&d2d), None, 40.0, 20.0, 1.0, &cfg, &cc, 0.0, WidgetHitZone::None, None, None, None, Some(&mut cc_boxes));
                rt.EndDraw(None, None).expect("EndDraw CC");
            }
            assert!(count_nonzero_dib_pixels(&sc.backbuf) > 1000, "CC Horology #{} must draw pixels", theme_idx);
            assert!(cc_boxes[5].visible, "CC Horology #{} must record Card box", theme_idx);

            // 5. Quick Apps
            cfg.apps_tile_shape = 4 + (theme_idx as u8);
            cfg.apps_show_plate = true;
            let mut ap_boxes = [ClockElemBox::default(); 5];
            unsafe {
                dc_rt.BindDC(sc.backbuf.mem_dc, &bind_rc).expect("BindDC");
                rt.BeginDraw();
                rt.Clear(Some(&clear_zero));
                draw_apps_widget_with_boxes(&rt, &dw, None, 40.0, 40.0, 1.0, &cfg, &app_tiles, None, Some(&mut ap_boxes));
                rt.EndDraw(None, None).expect("EndDraw Apps");
            }
            assert!(count_nonzero_dib_pixels(&sc.backbuf) > 1000, "Apps Horology #{} must draw pixels", theme_idx);
            assert!(ap_boxes[4].visible, "Apps Horology #{} must record Card box", theme_idx);

            // 6..19. All 14 Extended Widgets
            for id in ExtWidgetId::ALL {
                cfg.ext_widgets[id.idx()].apply_theme_preset(ExtWidgetTheme::HOROLOGY_FOLDER[theme_idx]);
                let mut e_boxes = [ClockElemBox::default(); 6];
                unsafe {
                    dc_rt.BindDC(sc.backbuf.mem_dc, &bind_rc).expect("BindDC");
                    rt.BeginDraw();
                    rt.Clear(Some(&clear_zero));
                    draw_ext_widget_with_boxes(&rt, &dw, Some(&d2d), None, 30.0, 30.0, 1.0, id, &cfg, &ext_state, &cc, WidgetHitZone::None, None, Some(&mut e_boxes));
                    rt.EndDraw(None, None).expect("EndDraw Ext");
                }
                assert!(
                    count_nonzero_dib_pixels(&sc.backbuf) > 400,
                    "Ext {:?} Horology #{} must draw visible instrument pixels",
                    id,
                    theme_idx
                );
                assert!(
                    e_boxes[5].visible,
                    "Ext {:?} Horology #{} must record Pen & Canvas Card box",
                    id,
                    theme_idx
                );
            }
        }

        // Verify Horology LRU GPU texture cache stayed strictly bounded (<= 16) and evicts cleanly
        let cache_len = crate::horology_pbr::cache_len_for_tests();
        assert!(cache_len > 0 && cache_len <= 16, "Horology RT LRU cache must be bounded (got {})", cache_len);
        crate::horology_pbr::evict_all();
        assert_eq!(crate::horology_pbr::cache_len_for_tests(), 0, "evict_all must release all cached RT textures");

        sc.release_idle_resources();
        unsafe {
            CoUninitialize();
        }
    }

